### 从零讲：凸函数的「差分多重集」表示

若整数函数相邻增量 $\Delta_j=\psi(j)-\psi(j-1)$ 不减，就称它离散凸。知道起点 $\psi(0)$ 和这些差分，就能通过前缀累加恢复整个函数。

![凸函数的差分与最小值](assets/f-slopes.svg)

两个独立子问题分配总量 $z$，要最小化 $\psi_1(z_1)+\psi_2(z_2)$、满足 $z_1+z_2=z$。每增加一份总量，可选某个子问题的下一个差分。因为各自差分不减，取全部差分中最小的 $z$ 个天然符合每组前缀约束。因此合并函数的起点是两个起点之和，差分则是两份有序差分的归并。

一个可选零结点的代价函数为在数量零、一时都取零，它的差分只有一个零；和它卷积就是插入这个零。最后求最小值时，只把所有负差分加到起点：负差分让代价下降，非负差分不再改善。

### 思路

令子树内固定权值和为 $A_v$，零有 $f_v$ 个，$B_v=A_v+f_v$。假设其中 $z$ 个零改为负一，其余改为正一，子树和就是 $B_v-2z$。

定义 $\psi_v(z)$ 为此时整棵子树的最小代价。先把孩子函数作最小加法卷积，记为 $\chi$。若当前结点固定，直接加 $|B_v-2z|$；若当前也是零，还可以由它自己贡献一个负一，所以先取 $\min(\chi(z),\chi(z-1))$，再加绝对值。

利用下节的差分表示，孩子合并等价于差分多重集合并；当前零的额外选择等价于插入一个零差分。最后加绝对值函数，其第 $j$ 个差分为
$$|B_v-2j|-|B_v-2(j-1)|.$$
它依次是若干个负二、可能一个零、若干个正二。因此按排名切开差分集合，前 $\lfloor B_v/2\rfloor$ 项减二，最后从第 $\lceil B_v/2\rceil+1$ 项起加二；所有范围截到实际长度，$B_v<0$ 时全加二。起点值则在孩子起点值总和上加 $|B_v|$。

两串不减差分按位置相加仍然不减，故每一层保持凸性。用可合并 Treap 维护值、子树大小、和、懒加标记，支持按键合并、按排名切分。根的最优代价为起点值加所有负差分之和。参考实现按 Treap 根的随机优先级选取分界，将另一棵树按键切分，再递归合并左右两侧；配合按排名切分与懒加，保守的期望时间上界为 $O(n\log^2 n)$，空间 $O(n)$。

### 参考代码

```cpp
// F. Plus Minus Tree
// 记 A_v = 子树内固定权值和、f_v = 子树内 0 的个数；把「子树里被改成 -1 的 0 的个数」记为 Y_v，
// 则子树和 S_v = B_v - 2Y_v（B_v = A_v + f_v），代价 Σ|S_v|。
// DP：ψ_v(z) = min(子树代价 | Y_v = z) =
//        |B_v - 2z| + χ_v(z)                 （v 固定，χ_v = 孩子们 ψ 的 min-plus 卷积）
//        |B_v - 2z| + min(χ_v(z), χ_v(z-1))  （v 是 0：Y_v = y_v + Σ Y_c）
// ψ_v 是凸的。用「base = ψ_v(0) + 升序差分多重集」表示：
//   卷积 = 差分多重集并；加 |B-2z| = 按 rank 前段 -2、后段 +2（B 为奇数时中间一格不动）；
//   侵蚀 min(χ(z),χ(z-1)) = 插入一个差分 0；答案 = base + 负差分之和。
// 多重集用可合并 treap（按 (值, id) 严格全序、支持按 rank 切分与懒加），总复杂度 O(n log^2 n)。
//
// ⚠️ 键必须带唯一 id：差分里等值元素极多（全 0 树几乎全是 0），若只用数值当键，
//    BST 下降会永远走同一侧，treap 退化成 O(n) 高的链——实测全 0 完全二叉树 n=2e5 要跑 30+ 秒。
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

struct Node {
    ll val, add, sum;
    unsigned prio, id;
    int sz;
    Node *l, *r;
};
static unsigned long long rngState = 88172645463325252ULL;
static inline unsigned rndPrio() {
    rngState ^= rngState << 13;
    rngState ^= rngState >> 7;
    rngState ^= rngState << 17;
    return (unsigned)(rngState >> 32);
}
static unsigned idCounter = 0;

// 严格全序：先比数值，再比唯一 id
static inline bool keyLess(const Node* a, const Node* b) {
    if (a->val != b->val) return a->val < b->val;
    return a->id < b->id;
}
static inline bool keyLessEq(const Node* a, const Node* b) { return !keyLess(b, a); }

static Node* newNode(ll v) {
    Node* x = new Node();
    x->val = v; x->add = 0; x->sum = v; x->prio = rndPrio(); x->id = ++idCounter; x->sz = 1;
    x->l = x->r = nullptr;
    return x;
}
static int nsz(Node* t) { return t ? t->sz : 0; }
static ll nsum(Node* t) { return t ? t->sum : 0; }
static void upd(Node* t) { if (t) { t->sz = 1 + nsz(t->l) + nsz(t->r); t->sum = t->val + nsum(t->l) + nsum(t->r); } }
static void apply(Node* t, ll d) { if (t) { t->val += d; t->add += d; t->sum += d * t->sz; } }
static void push(Node* t) { if (t && t->add) { apply(t->l, t->add); apply(t->r, t->add); t->add = 0; } }

// 按键切：a = 键 ≤ x 的，b = 键 > x 的
static void splitNode(Node* t, Node* x, Node*& a, Node*& b) {
    if (!t) { a = b = nullptr; return; }
    push(t);
    if (keyLessEq(t, x)) { splitNode(t->r, x, t->r, b); a = t; upd(a); }
    else { splitNode(t->l, x, a, t->l); b = t; upd(b); }
}
// 按数值切：a = 数值 ≤ v 的，b = 其余（等值元素全在 a 侧）
static void splitVal(Node* t, ll v, Node*& a, Node*& b) {
    if (!t) { a = b = nullptr; return; }
    push(t);
    if (t->val <= v) { splitVal(t->r, v, t->r, b); a = t; upd(a); }
    else { splitVal(t->l, v, a, t->l); b = t; upd(b); }
}
// 按 rank 切：a = 最小的 k 个（in-order 前缀）
static void splitSize(Node* t, int k, Node*& a, Node*& b) {
    if (!t) { a = b = nullptr; return; }
    push(t);
    if (nsz(t->l) >= k) { splitSize(t->l, k, a, t->l); b = t; upd(b); }
    else { splitSize(t->r, k - nsz(t->l) - 1, t->r, b); a = t; upd(a); }
}
static void insertNode(Node*& t, Node* x) {
    if (!t) { t = x; upd(t); return; }
    if (x->prio < t->prio) { push(t); splitNode(t, x, x->l, x->r); upd(x); t = x; return; }
    push(t);
    if (keyLessEq(x, t)) insertNode(t->l, x); else insertNode(t->r, x);
    upd(t);
}
static Node* mergeT(Node* a, Node* b) {
    if (!a) return b;
    if (!b) return a;
    if (a->prio < b->prio) { push(a); a->r = mergeT(a->r, b); upd(a); return a; }
    push(b); b->l = mergeT(a, b->l); upd(b); return b;
}
// 按 rank 区间 [lo,hi) 整体加 d
static void addRange(Node*& t, int lo, int hi, ll d) {
    if (lo >= hi || !t) return;
    Node *a, *b, *c;
    splitSize(t, lo, a, b);
    splitSize(b, hi - lo, b, c);
    apply(b, d);
    t = mergeT(mergeT(a, b), c);        // 三段按序接回（a ≤ b ≤ c）
}
// 两个 treap 求并（键全域可比，O(m log(n/m))）
static Node* unite(Node* a, Node* b) {
    if (!a) return b;
    if (!b) return a;
    if (a->prio < b->prio) {
        push(a);
        Node *b1, *b2;
        splitNode(b, a, b1, b2);
        a->l = unite(a->l, b1);
        a->r = unite(a->r, b2);
        upd(a);
        return a;
    }
    push(b);
    Node *a1, *a2;
    splitNode(a, b, a1, a2);
    b->l = unite(a1, b->l);
    b->r = unite(a2, b->r);
    upd(b);
    return b;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tc;
    cin >> tc;
    while (tc--) {
        int n;
        cin >> n;
        vector<int> a(n + 1);
        for (int i = 1; i <= n; i++) cin >> a[i];
        vector<vector<int>> adj(n + 1);
        for (int i = 0; i < n - 1; i++) {
            int u, v;
            cin >> u >> v;
            adj[u].push_back(v);
            adj[v].push_back(u);
        }
        vector<int> order;
        vector<char> vis(n + 1, 0);
        vector<int> par(n + 1, 0);
        order.push_back(1); vis[1] = 1;
        for (size_t i = 0; i < order.size(); i++) {
            int u = order[i];
            for (int w : adj[u]) if (!vis[w]) { vis[w] = 1; par[w] = u; order.push_back(w); }
        }
        vector<vector<int>> ch(n + 1);
        for (int v = 2; v <= n; v++) ch[par[v]].push_back(v);

        vector<ll> A(n + 1, 0);
        vector<int> F(n + 1, 0);
        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];
            if (a[v] != 0) A[v] += a[v]; else F[v] += 1;
            for (int c : ch[v]) { A[v] += A[c]; F[v] += F[c]; }
        }

        vector<Node*> T(n + 1, nullptr);
        vector<ll> base(n + 1, 0);
        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];
            for (int c : ch[v]) {
                T[v] = unite(T[v], T[c]);
                base[v] += base[c];
            }
            if (a[v] == 0) {                       // 侵蚀：min(χ(z), χ(z-1)) => 插一个 0
                insertNode(T[v], newNode(0));
            }
            ll B = A[v] + F[v];
            base[v] += llabs(B);
            int len = nsz(T[v]);
            ll c1raw = (B >= 2) ? ((B - 2) / 2 + 1) : 0;
            ll c2raw = (B >= 0) ? ((B + 1) / 2) : -((-B) / 2);
            int c1 = (int)max<ll>(0, min<ll>(len, c1raw));
            int c2 = (int)max<ll>(0, min<ll>(len, c2raw));
            if (c1 > c2) c1 = c2;
            addRange(T[v], 0, c1, -2);
            addRange(T[v], c2, len, 2);
        }
        ll ans = base[1];
        Node *neg = nullptr, *rest = nullptr;
        splitVal(T[1], -1, neg, rest);
        ans += nsum(neg);
        cout << ans << "\n";
    }
    return 0;
}
```

### 易错点

$B_v$ 可以为负，切点需截断。差分允许重复，要用唯一编号区分键；懒标记在切分、合并前下推。

## A. Min Max Game

### 题意

两人轮流合并相邻二进制数。先手用最大值，后手用最小值，最后剩一则先手胜，剩零则后手胜。

<!-- reusable-foundations:start -->

### 从零讲：博弈状态：自己的选择与对方的选择不同

两人轮流行动、都想获胜时，状态要包含足以决定合法动作的全部信息，并明确轮到谁。先约定正常玩法：没有合法动作的一方失败。

在有限且无环的状态图中，一个状态必胜，当且仅当存在一步能走到对手的必败状态；必败，当且仅当所有合法下一步都是对手的必胜状态。前者是“存在”，后者是“全部”，不能把对手的决定当成随机或替自己选择。

例如每次拿一或两颗石子：零颗必败，一、二颗必胜，三颗两种走法都交给对手必胜态，所以必败；四、五又能走向三，因此必胜。由此猜出三的倍数是败态，还须用这两种方向覆盖所有余数来证明。

若多个独立游戏可任选一个行动，且满足公平、有限、无环、正常玩法等条件，可给每个状态定义 SG 值：取所有后继 SG 值集合的 mex，即未出现的最小非负数。无后继时为零，多个独立游戏总 SG 为异或；不能将这个规则套到双方可选动作不同的非公平游戏。

按状态图顺序计算的成本为状态数加转移数，递归求解需记忆化，否则相同局面会反复展开。带环游戏可能出现平局或无限过程，直接照搬无环递推会循环；行动步数受限时，剩余步数也可能必须放入状态。

结论题要说明题目采用的终止和胜负规则。若最后行动者失败，或者一方只能水平走而另一方可四向走，必须重新建模，不能把经典取石子的公式直接移植。

### 从零讲：枚举与模拟：让代码和允许的动作一一对应

枚举是系统地检查所有候选；模拟是按题目规则推进状态。先写清一个候选是什么、有哪些动作、执行后哪些量改变，再决定循环边界。

例如从集合 $\{1,2,3\}$ 中选两个不同数：有序选择可枚举 $(i,j)$ 且 $i\ne j$，共六项；如果只关心无序的一对，就规定 $i<j$，得到 $(1,2)$、$(1,3)$、$(2,3)$，避免重复计数。同一个双循环，边界表达的是不同对象。

```cxx
for (int i = 0; i < n; ++i)
    for (int j = i + 1; j < n; ++j) {
        // 每一对不同位置恰好出现一次
    }
```

模拟例如计数器初始为零，依次读动作“加二、减一、加二”，状态为 $0\to2\to1\to3$。每一步都只读取该时刻允许的信息；若规则要求同时更新多个量，应先用旧状态算全部新量，不能让后一个更新误读前一个新值。

时间要数实际候选数和每个候选的工作。双循环可能是 $O(n^2)$，枚举长度为 $k$ 的二进制选择是 $O(2^k)$；候选少但每次又扫描全数组，也要乘上扫描成本。空间取决于是否需要保存历史。

全枚举的优势是思路直接，容易作为独立校验程序。剪枝必须证明被略去的分支不可能合法或更优，不能只因一个小例子没遇到答案就删候选。若直接枚举超时，先找重复工作、对称性、可维护的量或单调边界，再选择优化方法。

<!-- reusable-foundations:end -->

### 思路

先手每回合都能消掉一个零：选它和任意邻居即可，无论邻居是什么，零的数量都会少一。后手同理每回合能消掉一个一，而且两类数都不可能凭空增加。

总共 $n-1$ 回合，先手有 $\lfloor n/2\rfloor$ 次，后手有 $\lfloor(n-1)/2\rfloor$ 次。若零不超过先手的次数，先手一定能清空零；否则一不超过后手的次数，后手一定能清空一。两个条件恰好互补。因此设一有 $c$ 个，$2c\ge n$ 时输出先手，否则输出后手。计数 $O(n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        int ones = 0;
        for (int i = 0; i < n; i++) {
            int x;
            cin >> x;
            ones += x;
        }
        // 贝西走第 1、3、5...步（取 max），埃尔西走第 2、4、6...步（取 min）
        // 结论：1 的个数 >= ceil(n/2) 时先手贝西必胜，否则埃尔西胜
        cout << (2 * ones >= n ? "Bessie" : "Elsie") << '\n';
    }
    return 0;
}
```

### 易错点

偶数长度时零、一一样多，先手多一次操作，因此先手胜。

## B. Min Matrices

### 题意

将 $1\ldots n^2$ 各用一次填成方阵，使所有行最小值、列最小值合并后恰有 $k$ 个不同值。

<!-- reusable-foundations:start -->

### 从零讲：构造：找到一份合法对象，并解释它为何总能生成

构造题允许输出任意满足要求的对象。先区分“只需合法”与“还要求最小、最多或字典序最小”，不要额外发明优化目标。

例如要把从一到 $2k$ 的数字配成 $k$ 对，使每对和相同，可以配 $(1,2k),(2,2k-1),\ldots,(k,k+1)$，每对都为 $2k+1$。数字不重复，因为两半各用一次；也没有漏数。这个一般描述能直接转成循环。

![两端相向配对，每个数恰被使用一次且每对和相同](assets/foundations/construction.svg)

如果还要求最大化某项，先给任何方案都不能超越的上界，再展示构造确实达到上界；没有最优性要求时只证明合法和能完成即可。

一个完整构造应能回答：什么时候无解；输出对象是什么；每次允许的动作如何执行；后续所需的条件有没有被前面的动作破坏；数量、范围和边界是否满足。操作题还要区分目标排列和真正输出的操作序列。

验证构造不能只和另一程序逐字比较，因为合法答案可有多份。应将结果代回题目条件：检查长度、元素多重集合、限制、每步前后状态及目标。复杂度按生成和校验成本计算，输出本身有 $k$ 项就至少需要 $O(k)$ 时间。

### 从零讲：vector：长度可变的连续数组

`vector<T>` 保存一串同类型的元素，适合按下标访问、扫描、排序。`T` 是元素类型，例如 `vector<int>` 保存整数，`vector<pair<int,int>>` 保存整数对，`vector<vector<int>>` 可保存每个顶点各自的邻居。需要 `<vector>`。

```cxx
vector<int> a(3, 7);   // 三个元素，内容是 7、7、7
a.push_back(9);       // 在末尾追加，现在长度为 4
int x = a[1];         // 从 0 编号，这里得到 7
a[1] = 2;            // 改第二个元素
int n = int(a.size());
```

`vector<int> a(3)` 创建三个值为零的元素；`a.reserve(3)` 只预留容量，元素数仍为零，此时不能访问 `a[0]`。长度 `size()` 与容量 `capacity()` 是不同概念。

下标访问为 $O(1)$，遍历为 $O(n)$。末尾追加通常为 $O(1)$；容量不足时会分配更大的连续空间并搬移元素，这次可能为 $O(n)$，一连串追加的平均成本称为摊还 $O(1)$。中间插入或删除会搬移后续元素，最坏 $O(n)$。内存是元素量的 $O(n)$，并可能预留部分尚未使用的容量。

`begin()` 指向首元素，`end()` 指向尾后位置，`sort(a.begin(),a.end())` 操作整个数组。`a[i]` 不检查越界；下标须满足 $0\le i<\mathrm{size}$。`at(i)` 会检查越界并抛异常。空数组不能访问 `front()`、`back()`；`pop_back()` 也要求非空。

扩容后指向旧存储的迭代器、引用和指针会失效。遍历的同时 `push_back`，不能假定此前取得的引用仍可用。读取大数组的函数常用 `const vector<int>& a` 按常量引用传入，既不复制也禁止通过该引用修改；`vector<int> a` 按值传参则复制内容。选择副本还是引用取决于是否要保留独立数据。

<!-- reusable-foundations:end -->

### 思路

行、列各有 $n$ 个互异最小值。设同时是行最小和列最小的数有 $m$ 个，合并后就是 $2n-m$ 个。全局最小值一必在交集中，所以 $1\le m\le n$，即必须 $n\le k\le2n-1$。

反过来令 $m=2n-k$：先将 $1\ldots m$ 放在前 $m$ 个对角格；对第 $i>m$ 行，把 $i$ 放在第一列；对第 $j>m$ 列，把 $n+j-m$ 放在第一行。其余位置填剩下的大数，它们不会改变任何最小值。

例如 $n=3,k=5$ 时可填
$$\begin{pmatrix}1&4&5\\2&6&7\\3&8&9\end{pmatrix}.$$
行最小为 $1,2,3$，列最小为 $1,4,5$，恰有五种。构造时间、空间均为 $O(n^2)$。

#### 同时安排好的六个最小值实际放在哪里

取 $n=4,k=6$，交集需要 $m=2n-k=2$ 个数。按参考程序的顺序填入后，得到下图：

![四阶矩阵中一二同时属于行列最小值，三四只属行最小值，五六只属列最小值](assets/editorial-reasoning/arrays12-matrix-minima.svg)

蓝色的一、二在对角线上，同时承担所在行、列的最小值；绿色三、四在第一列，只承担各自行最小值，因为第一列已有一；橙色五、六在第一行，只承担各自列最小值，因为第一行已有一。三类格子互不重叠，共用掉一到六；`freev` 从六开始，第一次填普通格时加到七，其余数都更大，不会改动这些最小值。

因此行集合 $R=\{1,2,3,4\}$ 与列集合 $C=\{1,2,5,6\}$ 在同一张矩阵里同时实现，交集恰为 $\{1,2\}$，不是分别构造两个互相冲突的方案。原文的 $2n-m$ 正好把蓝色元素被两边统计的那一次重复减去。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

/*
B. Min Matrices
构造 n*n 矩阵，元素恰为 1..n^2 各一次，使 |f(A)| = k，
f(A) = 各行最小值与各列最小值构成的集合。

关键结论：1 一定同时是它所在行的行最小值与所在列的列最小值，故
|f(A)| = 2n - |交集|，其中「交集」是同时充当行最小、列最小的值。
交集大小在 [1, n] 之间，于是可行区间恰为 k ∈ [n, 2n-1]。
记 m = 2n - k（公共最小值个数，即交集大小），构造：
  · 对角线 (i,i) = i（i = 1..m）：这 m 个数既是最小又是列最小；
  · 第 1 列的第 i 行（i > m）放 i：它只当行最小（该列最小是 1）；
  · 第 1 行的第 j 列（j > m）放 n + j - m：它只当列最小（该行最小是 1）；
  · 其余格子从 2n - m + 1 开始顺次填大数。
此时 f(A) = [1, 2n-m]，恰好 k 个数。
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n, k;
        cin >> n >> k;
        if (k < n || k > 2 * n - 1) {          // 可行区间之外无解
            cout << -1 << '\n';
            continue;
        }
        int m = 2 * n - k;                      // 公共最小值个数（交集大小）
        int freev = 2 * n - m;                  // 自由格从 freev+1 开始顺次填
        vector<vector<int>> A(n + 1, vector<int>(n + 1, 0));
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                int v;
                if (i == j && i <= m) v = i;              // 公共最小值
                else if (j == 1 && i > m) v = i;          // 只作行最小
                else if (i == 1 && j > m) v = n + (j - m); // 只作列最小
                else v = ++freev;                          // 其余大数
                A[i][j] = v;
            }
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (j > 1) cout << ' ';
                cout << A[i][j];
            }
            cout << '\n';
        }
    }
    return 0;
}
```

### 易错点

必须先检查可行区间，否则构造中的行列下标会失效。

## C1. Floor of MEX (Easy Version)

### 题意

给定每个 $k$ 对应的 $a_k=\operatorname{mex}\{\lfloor y/k\rfloor:y\in A\}$，恢复一个集合 $A\subseteq\{0,\ldots,n-1\}$。保证存在解。

<!-- reusable-foundations:start -->

### 从零讲：构造：找到一份合法对象，并解释它为何总能生成

构造题允许输出任意满足要求的对象。先区分“只需合法”与“还要求最小、最多或字典序最小”，不要额外发明优化目标。

例如要把从一到 $2k$ 的数字配成 $k$ 对，使每对和相同，可以配 $(1,2k),(2,2k-1),\ldots,(k,k+1)$，每对都为 $2k+1$。数字不重复，因为两半各用一次；也没有漏数。这个一般描述能直接转成循环。

![两端相向配对，每个数恰被使用一次且每对和相同](assets/foundations/construction.svg)

如果还要求最大化某项，先给任何方案都不能超越的上界，再展示构造确实达到上界；没有最优性要求时只证明合法和能完成即可。

一个完整构造应能回答：什么时候无解；输出对象是什么；每次允许的动作如何执行；后续所需的条件有没有被前面的动作破坏；数量、范围和边界是否满足。操作题还要区分目标排列和真正输出的操作序列。

验证构造不能只和另一程序逐字比较，因为合法答案可有多份。应将结果代回题目条件：检查长度、元素多重集合、限制、每步前后状态及目标。复杂度按生成和校验成本计算，输出本身有 $k$ 项就至少需要 $O(k)$ 时间。

### 从零讲：前缀和：一段和由两段前缀相减

一串数需要反复询问连续一段的总和，逐段扫描会重复加很多相同元素。先保存从头到每个位置的累计量，就能复用这些工作。

对从一编号的数组定义 $S_0=0$，$S_i=a_1+\cdots+a_i$。例如 $a=[2,3,1,4]$，前缀为 $S=[0,2,5,6,10]$。

![S4 包含整段，S1 是多算的前缀，减去后留下第 2 至 4 项](assets/foundations/prefix.svg)

查询 $[2,4]$ 时，$S_4$ 包含第一个数，减去 $S_1$ 后留下 $3+1+4=8$。一般地，$S_r-S_{l-1}$ 中前 $l-1$ 项逐项抵消，只留下第 $l$ 到第 $r$ 项。

```cxx
vector<long long> s(n + 1, 0);
for (int i = 1; i <= n; ++i) s[i] = s[i - 1] + a[i];
long long sum = s[r] - s[l - 1];
```

预处理 $O(n)$ 时间和空间，每次查询 $O(1)$，比 $q$ 次逐段扫描的最坏 $O(nq)$ 更适合大量静态区间和。若使用从零编号的原数组，也可定义 $P_i$ 为前 $i$ 项之和，查询闭区间 $[l,r]$ 为 $P_{r+1}-P_l$；不要混用两套下标。

前缀可以累积满足条件的次数，把每项变成零或一；也可以保存异或，此时相同前缀通过异或抵消。最小值没有同样的可逆减法，不能直接套区间最小值。原数组改变后，后续许多前缀都受影响；频繁在线修改时可考虑树状数组或线段树。

首个空前缀零不可漏，累加类型要覆盖总和。数学上的减法可能得到负值，别让无符号类型把它变成巨大正数。

### 从零讲：差分：把区间的变化写在两个边界

很多次操作都给一整段加同一个数，最后才需要所有位置的结果。逐项修改会重复扫描；差分只记录“从哪里开始多这一份、从哪里停止”。

定义 $D_1=a_1$，$D_i=a_i-a_{i-1}$。从左累计 $D$ 就能恢复 $a$。给闭区间 $[l,r]$ 加 $v$，仅需 $D_l$ 加 $v$、$D_{r+1}$ 减 $v$：第 $l$ 位开始，前缀多出 $v$；到第 $r+1$ 位，额外的一份被抵消。

![第 2 位开始加三，第 5 位停止；只有第 2 至 4 位被改变](assets/foundations/difference.svg)

例如五个零上给 $[2,4]$ 加三，差分事件为 $[0,3,0,0,-3]$，累计得到 $[0,3,3,3,0]$。两个标记不表示只修改了两个原元素。

```cxx
vector<long long> d(n + 2, 0);
d[l] += v;
d[r + 1] -= v;
long long current = 0;
for (int i = 1; i <= n; ++i) {
    current += d[i];
    // current 是该位置受到的总增量
}
```

$q$ 次区间加与最后恢复共 $O(n+q)$，空间 $O(n)$。如果初始数组非零，可先构造它的差分，或在恢复增量后加回原值。右边界要标在后一位，数组须留出 `n+1`；闭区间和半开区间的停止位置不能混用。

差分适合离线集中恢复。若每次操作后立刻查询任意位置，仅存差分并不能自动做到常数时间，需要动态前缀数据结构。坐标非常大但事件少时，应排序事件或离散化，不能按最大坐标盲目分配数组。

### 从零讲：vector：长度可变的连续数组

`vector<T>` 保存一串同类型的元素，适合按下标访问、扫描、排序。`T` 是元素类型，例如 `vector<int>` 保存整数，`vector<pair<int,int>>` 保存整数对，`vector<vector<int>>` 可保存每个顶点各自的邻居。需要 `<vector>`。

```cxx
vector<int> a(3, 7);   // 三个元素，内容是 7、7、7
a.push_back(9);       // 在末尾追加，现在长度为 4
int x = a[1];         // 从 0 编号，这里得到 7
a[1] = 2;            // 改第二个元素
int n = int(a.size());
```

`vector<int> a(3)` 创建三个值为零的元素；`a.reserve(3)` 只预留容量，元素数仍为零，此时不能访问 `a[0]`。长度 `size()` 与容量 `capacity()` 是不同概念。

下标访问为 $O(1)$，遍历为 $O(n)$。末尾追加通常为 $O(1)$；容量不足时会分配更大的连续空间并搬移元素，这次可能为 $O(n)$，一连串追加的平均成本称为摊还 $O(1)$。中间插入或删除会搬移后续元素，最坏 $O(n)$。内存是元素量的 $O(n)$，并可能预留部分尚未使用的容量。

`begin()` 指向首元素，`end()` 指向尾后位置，`sort(a.begin(),a.end())` 操作整个数组。`a[i]` 不检查越界；下标须满足 $0\le i<\mathrm{size}$。`at(i)` 会检查越界并抛异常。空数组不能访问 `front()`、`back()`；`pop_back()` 也要求非空。

扩容后指向旧存储的迭代器、引用和指针会失效。遍历的同时 `push_back`，不能假定此前取得的引用仍可用。读取大数组的函数常用 `const vector<int>& a` 按常量引用传入，既不复制也禁止通过该引用修改；`vector<int> a` 按值传参则复制内容。选择副本还是引用取决于是否要保留独立数据。

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cxx
int a = 100000, b = 100000;
long long wrong = a * b;      // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

<!-- reusable-foundations:end -->

### 思路

商等于 $j$ 的所有值恰好组成区间 $[jk,(j+1)k-1]$。要让 mex 为 $a_k$，小于 $a_k$ 的每个商都必须出现，而商 $a_k$ 不能出现。

![商对应连续块](assets/c-intervals.svg)

所以先禁止每个区间 $[a_kk,(a_k+1)k-1]$，再把所有没被禁止的数都选上。为什么不用再检查小于 mex 的商？题目保证存在原集合，它一定包含于我们留下的集合；增加允许的元素只会多命中必要块，又不会选进禁止块，因此依旧合法。

差分标记区间覆盖次数，扫描找覆盖为零的位置。时间、空间都是 $O(n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

/*
C1. Floor of MEX (Easy Version)
给定 a_1..a_n，要找一个 B ⊆ {0..n-1} 使 f(B,k) = mex{floor(y/k) : y∈B} = a_k。
思路：把「f(B,k) = a_k」拆成两条
  (1) a_k 不能出现在商集合里  ⟺  B 中没有任何 y ∈ [a_k*k, (a_k+1)k - 1]；
  (2) 每个 j < a_k 都要出现 ⟺ B 在每个块 [jk, (j+1)k-1] 里都有人。
把所有禁止区间 [a_k*k, (a_k+1)k-1] 标出来，取补集得集合 M。
可证：所有合法 B 都满足 (1)，即 B ⊆ M；而 M 本身又天然满足 (2)
（因为题目保证存在解，真正的那组 B 落在 M 里，补齐到 M 只会多命中块、不会引入 a_k）。
于是直接输出 M 即可。
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<int> a(n + 1);
        for (int k = 1; k <= n; k++) cin >> a[k];
        // 禁止区间差分标记（[L,R] 内的 y 一律不能选）
        vector<int> d(n + 2, 0);
        for (int k = 1; k <= n; k++) {
            long long L = 1LL * a[k] * k;
            long long R = 1LL * (a[k] + 1) * k - 1;
            if (L > n - 1) continue;
            if (R > n - 1) R = n - 1;
            d[(int)L]++;
            d[(int)R + 1]--;
        }
        vector<int> ans;
        int cur = 0;
        for (int y = 0; y < n; y++) {
            cur += d[y];
            if (cur == 0) ans.push_back(y);
        }
        cout << ans.size() << '\n';
        for (size_t i = 0; i < ans.size(); i++) {
            if (i) cout << ' ';
            cout << ans[i];
        }
        cout << '\n';
    }
    return 0;
}
```

### 易错点

禁止区间要与 $[0,n-1]$ 取交集。这里可以全选依赖题面保证有解。

## C2. Floor of MEX (Hard Version)

### 题意

与 C1 的条件相同，改为统计所有满足这些 mex 的集合数，模 $10^9+7$。

