#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    char task; cin >> task;
    if (task == 'A') {
        const string digits = "5686916124919823647759503875815861830379270588570991944686338516346707827689565614010094809128502533";
        int days[] = {0,31,28,31,30,31,30,31,31,30,31,30,31};
        int answer = 0;
        for (int month=1;month<=12;++month) for (int day=1;day<=days[month];++day) {
            string target = "2023";
            target += char('0'+month/10); target += char('0'+month%10);
            target += char('0'+day/10); target += char('0'+day%10);
            int matched = 0;
            for (char c : digits) if (matched<8 && c==target[matched]) ++matched;
            answer += (matched==8);
        }
        cout << answer << '\n';
    } else {
        const long long n = 23333333;
        const long double target = 11625907.5798L;
        long double bestDifference = 1e100L; long long answer = -1;
        for (long long x=1;x*2<n;++x) {
            long double p=(long double)x/n, q=1-p;
            long double entropy=-x*p*log2l(p)-(n-x)*q*log2l(q);
            long double difference=fabsl(entropy-target);
            if (difference<bestDifference) { bestDifference=difference; answer=x; }
        }
        cout << answer << '\n';
    }
}
```

### 易错点

日期统计的是不同日期，而不是不同选取方案；2023 年不是闰年。熵公式按每个字符求和，零和一的出现次数还要分别乘上；浮点比较不能使用直接相等。

## C. 冶炼金属

[题目](https://www.luogu.com.cn/problem/P9240)

### 题意

每条记录满足 $\lfloor A/V\rfloor=B$。所有记录共用一个正整数转换率 $V$，求可能的最小值和最大值。

<!-- reusable-foundations:start -->

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cxx
int a = 100000, b = 100000;
long long wrong = a * b;      // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

<!-- reusable-foundations:end -->

### 思路

由 $BV\le A<(B+1)V$，一条记录给出的整数区间为
$$\left[\left\lfloor\frac{A}{B+1}\right\rfloor+1,\ \left\lfloor\frac AB\right\rfloor\right].$$
把所有下界取最大值、所有上界取最小值，即为交集的两端。题目保证交集非空。时间复杂度 $O(N)$，额外空间 $O(1)$。

### 两条边界分别表示“够做”和“不够再做一个”

实际投入七十五份、产出三份时，转换率十九可做三份剩十八，二十五可恰做三份；十八却能做四份，二十六只能做两份。所以一条记录允许整个整数段十九至二十五，不能只拿七十五除三当作唯一转换率。

做三份够用，要求 $3V\le75$；做四份不够，要求 $4V>75$，两句合起来才与记录等价。一般正整数 B 给出 $V\le\lfloor A/B\rfloor$ 和 $V\ge\lfloor A/(B+1)\rfloor+1$。例如十二份产三份时，$12/(3+1)=3$，下界必须再加一成为四；取三实际会产四份，取四才恰好产三份，因此即使整除也要加一。

样例三条记录依次允许 $[19,25]$、$[18,26]$、$[20,29]$；维护的端点从 $[1,10^9]$ 依次变成 $[19,25]$、$[19,25]$、$[20,25]$。区间交集中的每个 V 对每条记录都同时满足上述两句；记录的剩余原料不跨次累计，所以这些要求可以同时实现。任何交集外的数又至少违反一条记录。故交集两端确为最小和最大答案，题面保证非空，B 为正也保证取整除法有定义。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n; cin >> n;
    long long lo = 1, hi = 1000000000LL;
    while (n--) {
        long long a, b; cin >> a >> b;
        lo = max(lo, a / (b + 1) + 1); // 严格大于转为整数下界
        hi = min(hi, a / b);
    }
    cout << lo << ' ' << hi << '\n';
}
```

### 易错点

下界是 $\lfloor A/(B+1)\rfloor+1$。不能把它写成 $\lceil A/(B+1)\rceil$：当整除时，后者会错误地包含能多炼出一个成品的转换率。

## D. 飞机降落

[题目](https://www.luogu.com.cn/problem/P9241)

### 题意

每架飞机允许开始降落的时间为 $[T_i,T_i+D_i]$，占用跑道 $L_i$ 时间。判断能否安排全部飞机，飞机数不超过 $10$。

<!-- reusable-foundations:start -->

### 从零讲：枚举与模拟：让代码和允许的动作一一对应

枚举是系统地检查所有候选；模拟是按题目规则推进状态。先写清一个候选是什么、有哪些动作、执行后哪些量改变，再决定循环边界。

例如从集合 $\{1,2,3\}$ 中选两个不同数：有序选择可枚举 $(i,j)$ 且 $i\ne j$，共六项；如果只关心无序的一对，就规定 $i<j$，得到 $(1,2)$、$(1,3)$、$(2,3)$，避免重复计数。同一个双循环，边界表达的是不同对象。

```cxx
for (int i = 0; i < n; ++i)
    for (int j = i + 1; j < n; ++j) {
        // 每一对不同位置恰好出现一次
    }
```

模拟例如计数器初始为零，依次读动作“加二、减一、加二”，状态为 $0\to2\to1\to3$。每一步都只读取该时刻允许的信息；若规则要求同时更新多个量，应先用旧状态算全部新量，不能让后一个更新误读前一个新值。

时间要数实际候选数和每个候选的工作。双循环可能是 $O(n^2)$，枚举长度为 $k$ 的二进制选择是 $O(2^k)$；候选少但每次又扫描全数组，也要乘上扫描成本。空间取决于是否需要保存历史。

全枚举的优势是思路直接，容易作为独立校验程序。剪枝必须证明被略去的分支不可能合法或更优，不能只因一个小例子没遇到答案就删候选。若直接枚举超时，先找重复工作、对称性、可维护的量或单调边界，再选择优化方法。

### 从零讲：vector：长度可变的连续数组

`vector<T>` 保存一串同类型的元素，适合按下标访问、扫描、排序。`T` 是元素类型，例如 `vector<int>` 保存整数，`vector<pair<int,int>>` 保存整数对，`vector<vector<int>>` 可保存每个顶点各自的邻居。需要 `<vector>`。

```cxx
vector<int> a(3, 7);   // 三个元素，内容是 7、7、7
a.push_back(9);       // 在末尾追加，现在长度为 4
int x = a[1];         // 从 0 编号，这里得到 7
a[1] = 2;            // 改第二个元素
int n = int(a.size());
```

`vector<int> a(3)` 创建三个值为零的元素；`a.reserve(3)` 只预留容量，元素数仍为零，此时不能访问 `a[0]`。长度 `size()` 与容量 `capacity()` 是不同概念。

下标访问为 $O(1)$，遍历为 $O(n)$。末尾追加通常为 $O(1)$；容量不足时会分配更大的连续空间并搬移元素，这次可能为 $O(n)$，一连串追加的平均成本称为摊还 $O(1)$。中间插入或删除会搬移后续元素，最坏 $O(n)$。内存是元素量的 $O(n)$，并可能预留部分尚未使用的容量。

`begin()` 指向首元素，`end()` 指向尾后位置，`sort(a.begin(),a.end())` 操作整个数组。`a[i]` 不检查越界；下标须满足 $0\le i<\mathrm{size}$。`at(i)` 会检查越界并抛异常。空数组不能访问 `front()`、`back()`；`pop_back()` 也要求非空。

扩容后指向旧存储的迭代器、引用和指针会失效。遍历的同时 `push_back`，不能假定此前取得的引用仍可用。读取大数组的函数常用 `const vector<int>& a` 按常量引用传入，既不复制也禁止通过该引用修改；`vector<int> a` 按值传参则复制内容。选择副本还是引用取决于是否要保留独立数据。

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cxx
int a = 100000, b = 100000;
long long wrong = a * b;      // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

### 从零讲：位运算：把非负整数看成一组二进制开关

五写成二进制为 $0101_2$，三为 $0011_2$。同一列各代表一位：按位与 `&` 两边都为一才得一，按位或 `|` 任一为一就得一，按位异或 `^` 不同才为一。所以 $5\mathbin{\&}3=1$，$5\mathbin{|}3=7$，$5\mathbin{\oplus}3=6$。

![相同数值分别写成每一位，逐列计算与、或、异或](assets/foundations/bits.svg)

`1ULL << k` 把一移到第 $k$ 位。对非负无符号整数，`(mask >> k) & 1ULL` 读该位，`mask | (1ULL<<k)` 置一，`mask & ~(1ULL<<k)` 清零，`mask ^ (1ULL<<k)` 翻转。最低位编号为零。

```cxx
unsigned long long mask = 5; // 第 0、2 位为一
bool has = (mask >> 2) & 1ULL; // true
mask |= 1ULL << 1;             // 变成 7
```

位移次数必须小于类型位宽，且不能为负；不要用普通 `1` 去移到超出 int 范围的位置。C++17 有符号负数右移和溢出的规则不适合直接套“乘除二的幂”，用明确范围的无符号数更容易保证行为。`^` 是异或，绝不是乘方。

逻辑与 `&&`、逻辑或 `||` 将整体条件视为真假，并会短路；按位 `&`、`|` 逐位计算，不会因此跳过右侧表达式。运算符优先级可能与直觉不同，写 `(mask & bit) != 0`，别省掉关键括号。

固定机器字内的一次位运算按 $O(1)$ 估算；枚举全部 $k$ 位状态仍有 $2^k$ 种，不能因为每次运算快就忽略状态数。`x & (x-1)` 对正无符号数清掉最低的一位；GCC 的 `__builtin_popcountll(x)` 统计一的数量，注意实参位宽与具体编译器支持。



### 从零讲：集合状态动态规划与递增掩码

只有十几件对象时，常用整数的二进制位表示已选集合：第 $i$ 位是 $1$ 表示选了编号 $i$。例如三个对象编号 $0,1,2$，二进制 `101` 是集合 $\{0,2\}$。`mask >> i & 1` 读取该位，`mask | (1 << i)` 把它设为 $1$；只能在对象尚未选入时进行“新增对象”的转移，否则会重复使用。

先定义一个独立问题：三件任务的固定代价为 $2,5,3$，问每个集合内任务总代价。`dp[mask]` 表示这个集合的最小总代价，空集为 $0$，其余先用 `INF` 标为未到达。对于 `101`，已有任务 $0/2$，代价 $2+3=5$；再加入任务 $1$，得到 `111`，候选 $5+5=10$。其他加入顺序也到同一个集合，用 `min` 合并，结果仍是 $10$。

```cxx
vector<int> subset_totals(const vector<int>& cost) {
    int n = static_cast<int>(cost.size());
    const int INF = 1000000000;
    vector<int> dp(1 << n, INF);
    dp[0] = 0;
    for (int mask = 0; mask < (1 << n); ++mask) {
        if (dp[mask] == INF) continue;
        for (int i = 0; i < n; ++i) if (!(mask >> i & 1)) {
            int next = mask | (1 << i);
            dp[next] = min(dp[next], dp[mask] + cost[i]);
        }
    }
    return dp;
}
```

这里要求代价非负、总和小于 `INF`，且 $n<31$ 使 `1<<n` 在有符号 `int` 范围内；实际还必须让 $2^n$ 个元素能放进内存。代码对 $2,5,3$ 返回按掩码 $0$ 到 $7$ 排列的 $[0,2,5,7,3,5,8,10]$。空任务列表只有空集，返回 $[0]$。

从 `mask` 添加一个原本为零的位，相当于加上正数 $2^i$，故 `next > mask`。按整数从小到大扫描时，来源已经处理，目标还在后面；即使新任务代价为零，集合仍严格增加，不会产生依赖环。每个集合尝试 $n$ 件对象，时间 $O(n2^n)$，状态空间 $O(2^n)$。

把许多历史顺序合并到同一集合，必须证明未来只关心集合及所保存的最优量。固定任务总代价不依赖顺序，所以这里成立；若代价取决于“上一件是哪件”，就需要再记最后一个对象，不能只保留集合。这一证明必须针对所解问题补上，二进制表示本身不提供正确性。

<!-- reusable-foundations:end -->

### 思路

用一个二进制集合表示已经降落的飞机，令 $f[S]$ 为完成这些飞机的最早时刻。初始 $f[\varnothing]=0$，其他状态不可达。

加入尚未降落的飞机 $i$ 时，最早开始时刻为 $s=\max(f[S],T_i)$。若 $s\le T_i+D_i$，用 $s+L_i$ 更新 $f[S\cup\{i\}]$。同一集合只保留最早结束的安排，因为更早空出的跑道可以等待，绝不会更差。全集状态可达即输出 `YES`。

时间复杂度 $O(N2^N)$，空间复杂度 $O(2^N)$。

### 本题开始窗口、跑道占用与一次真的状态更新

取三架飞机 $A:(T,D,L)=(0,8,2)$、$B:(2,2,2)$、$C:(0,0,4)$。图把“允许开始的窗口”和“实际占用跑道的时间”画在同一时间轴上：

![三架真实飞机的窗口与集合状态实际操作数](assets/editorial-reasoning/counting13-planes.svg)

合法顺序是 $C,B,A$，占用依次为 $[0,4],[4,6],[6,8]$。$B$ 在最晚允许的 $4$ 开始、到 $6$ 结束仍合法，$C$ 的开始窗口更是只有时刻 $0$；不能拿结束时刻检查燃油截止。按位 $0/1/2$ 表示 $A/B/C$，实际转移是 $000\to100\to110\to111$，最早结束时刻为 $0\to4\to6\to8$。

其中给已完成的 $\{C\}$ 加 $B$，完整运算数是 `start=max(4,2)=4`，检查 $4\le2+2$，再以 $4+2=6$ 更新 $f[110]$。前两项确保跑道已空、飞机已到；不晚于截止确保它还能开始。安排此前集合的合法历史后，再接这一架，所有约束就同时满足。反之，任何合法顺序的下一架都在枚举中，其最早开始仍合法，因此不会遗漏。

同一集合 $\{A,B\}$，顺序 $A,B$ 可在 $4$ 结束，$B,A$ 则在 $6$ 结束；保留前者即可，它可等到 $6$ 后照搬任何后续，其他飞机不会受过去顺序影响。`min` 合并的是最早时刻，不是把方案数量相加。先做 $A$ 后尝试 $C$ 时最早开始为 $2>0$，此分支才应剪掉。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int tests; cin >> tests;
    while (tests--) {
        int n; cin >> n;
        vector<long long> t(n), d(n), len(n);
        for (int i = 0; i < n; ++i) cin >> t[i] >> d[i] >> len[i];
        const long long INF = (1LL << 60);
        vector<long long> f(1 << n, INF); f[0] = 0;
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (f[mask] == INF) continue;
            for (int i = 0; i < n; ++i) if (!(mask >> i & 1)) {
                long long start = max(f[mask], t[i]);
                if (start <= t[i] + d[i]) {
                    int next = mask | (1 << i);
                    f[next] = min(f[next], start + len[i]);
                }
            }
        }
        cout << (f.back() == INF ? "NO" : "YES") << '\n';
    }
}
```

### 易错点

截止时间约束开始降落；等号合法。允许 $L_i=0$，状态仍会增加一架飞机，不会造成循环。每组测试都要重新初始化状态。

## E. 接龙数列

[题目](https://www.luogu.com.cn/problem/P9242)

### 题意

从原序列中删除尽量少的数，使相邻保留数字满足“前一个末位等于后一个首位”。相对顺序不能改变。

<!-- reusable-foundations:start -->

### 从零讲：string：字符、下标与子串

`string` 保存字符序列。`string s="abca";` 的长度为四，下标从零开始，`s[0]=='a'`、`s[3]=='a'`。字符用单引号，字符串用双引号；二者类型不同。需要 `<string>`。

`cin >> s` 读到空白停止；整行含空格时使用 `getline`，并留意前一次格式化输入残留的换行。`s.size()` 是字符单元数量，不一定等于 UTF-8 中文字数；竞赛英文小写字母题通常一个字符对应一个单元。

```cxx
string s = "abca";
string middle = s.substr(1, 2); // 从下标 1 开始取 2 个字符，得到 bc
size_t pos = s.find('c');       // 得到 2；找不到是 string::npos
if (pos != string::npos) cout << s[pos];
```

`substr(start,length)` 的第二项是长度，不是右端点。普通下标访问为 $O(1)$；复制长为 $k$ 的子串需要 $O(k)$ 时间和空间，循环里反复截取可能累积成平方成本。字符串比较按第一个不同字符决定字典序，公共前缀可能需要线性比较。

常见字符转数字是 `c-'0'`，前提 `c` 在 `'0'` 到 `'9'`。修改原串可用 `for(char& c:s)`，只读使用 `char c`。`reverse(s.begin(),s.end())` 原地翻转；若还需要原串，应先复制。空串不能访问首尾，尾后位置不能当普通字符读取。



### 从零讲：array、元素引用与最大值迭代器

`array<int, 4>` 是连续存放四个整数的固定长度容器，长度是类型的一部分，不能 `push_back`。`a[i]` 在合法下标内读写一个元素，时间 $O(1)$，不自动检查越界。`array<int, 10> zeros{};` 的空花括号把所有整数初始化为零；局部的 `array<int, 10> zeros;` 没有这个保证，不能在赋值前读取其元素。存储 $n$ 个元素需要 $O(n)$ 空间。

范围循环 `for (int x : a)` 每次取得副本，改 `x` 不改数组；`for (int &x : a)` 取得元素引用，改 `x` 就改该元素。引用只能在原容器仍存在、相应元素仍有效时使用；本地数组的引用不能返回给调用者继续使用。

`max_element(first, last)` 来自 `<algorithm>`，检查左闭右开区间，返回**第一个最大元素所在的迭代器**，既不是最大值，也不是下标。用 `*it` 读取它指向的值。数组的 `begin()` 指向首元素，`end()` 指向末尾之后，后者不能解引用。

```cxx
array<int, 4> a{3, 7, 7, 2};
auto it = max_element(a.begin(), a.end()); // it == a.begin()+1，*it == 7
array<int, 3> b{2, 4, 6};
for (int x : b) ++x;  // 只改副本，b仍为2/4/6
for (int &x : b) ++x; // b变成3/5/7
array<int, 10> zeros{};
auto zero_it = max_element(zeros.begin(), zeros.end()); // 指向第一个0
vector<int> empty;
auto missing = max_element(empty.begin(), empty.end()); // missing == empty.end()
// 不能解引用missing。
```

若区间有 $n>0$ 项，最大值查找做 $n-1$ 次比较，时间 $O(n)$、额外空间 $O(1)$；空区间不比较，直接返回 `last`。因此通用写法须先确认结果不等于 `end()`。固定长度为十的数组一定非空，取其中最大值时这一检查由类型长度保证，但长度为零的 `array<int, 0>` 就没有这个保证。循环修改数组后，旧迭代器仍指向同一位置，所读数值会随元素改变，并不是数值快照。

<!-- reusable-foundations:end -->

### 思路

等价于求最长接龙子序列。扫描原序列，用 $f[d]$ 表示已处理部分中、末位为 $d$ 的最长接龙长度。当前数首位为 $a$、末位为 $b$，可以接在末位为 $a$ 的序列后，故
$$f[b]\gets\max(f[b],f[a]+1).$$
不选择当前数时旧状态保留。答案为 $N-\max_d f[d]$。读取数字的总位数记为 $D$，时间复杂度 $O(D)$，额外状态空间 $O(1)$。

### 本题一次读入究竟接在哪条旧链之后

输入五个有身份的数 $A=12,B=22,C=22,D=32,E=23$，只能删、不能换顺序。图中保留 $A/B/C/E$，只删 $D$：

![五个原序列对象和读旧状态的实际候选](assets/editorial-reasoning/counting13-chain.svg)

前面依次读入 $12,22,22$ 后，`best[2]` 从 $1$ 到 $2$ 再到 $3$，两个 $22$ 是两个不同位置，都能使用一次。遇到 $32$，首位是 $3$，旧 `best[3]=0` 给出的新候选只有 $1$；旧 `best[2]=3` 更长，要保留。再遇到 $23$，从旧 `best[2]=3` 接上得到 `best[3]=4`。最终删除 $5-4=1$ 个。

对当前首位 $a$、末位 $b$，每条选择当前数的合法链，去掉最后这个数后必是旧的末位 $a$ 链；反过来给这样的旧链接上当前数必合法。于是最大新增长度恰为旧 $f[a]+1$，与不选当前数的旧 $f[b]$ 取最大就覆盖两种情况，其他末位不变。旧值为零时表示没有非空链，候选 $1$ 让当前数自成新链，并不是说空链真的有末位 $a$。

未来只看链的末位，因此同末位较短链都可被较长链替代。代码先算 `candidate` 再写入，使这一轮只使用一次当前数，即使 $a=b$ 也是旧长度加一。末位 $0$ 也要保留状态，例如正整数 $10$；输入为正并不意味着末位不能为零。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n; cin >> n;
    array<int, 10> best{};
    for (int i = 0; i < n; ++i) {
        string s; cin >> s;
        int first = s.front() - '0', last = s.back() - '0';
        int candidate = best[first] + 1; // 先用更新前的状态
        best[last] = max(best[last], candidate);
    }
    cout << n - *max_element(best.begin(), best.end()) << '\n';
}
```

### 易错点

不能排序原数组。接龙允许删除中间元素，但不允许改变顺序；答案是总长度减去最长保留长度。

## F. 岛屿个数

[题目](https://www.luogu.com.cn/problem/P9243)

### 题意

陆地按上下左右四个方向连成岛屿。被其他岛屿的四方向闭环包住的岛屿不计数，求最外层岛屿个数。

<!-- reusable-foundations:start -->

### 从零讲：图的表示、BFS 与 DFS

图由顶点与边组成，适合表达“哪些对象之间能一步到达”。有向边只允许一个方向；无向边需保存两个方向。邻接表 `vector<vector<int>> graph(n)` 为每个顶点保存邻居，空间 $O(n+m)$，无向边在表中出现两次。

以边 $0-1,0-2,1-3$ 为例，从零出发：

![BFS 按距离分层，DFS 沿一条分支深入再返回](assets/foundations/graphs.svg)

#### BFS 为什么得到最少边数

初始顶点距离为零，入先进先出的队列。弹出顶点时，将尚未到达的邻居距离设为当前距离加一，并立刻标记入队。距离为一的顶点都会先于距离为二的处理，因此第一次发现就是最少边数。

```cxx
vector<int> distance(n, -1);
queue<int> q;
distance[start] = 0; q.push(start);
while (!q.empty()) {
    int u = q.front(); q.pop();
    for (int v : graph[u]) if (distance[v] == -1) {
        distance[v] = distance[u] + 1;
        q.push(v);
    }
}
```

适用于无权或所有边代价相同的最少步数。边权不同，第一次发现未必费用最小，不能继续套这一结论。多起点 BFS 先把所有合法起点设零并入队。

#### DFS 的调用代表一整块未探索区域

DFS 标记当前点后，递归处理每个尚未访问的邻点；也可用显式栈。上例可能按 $0,1,3,2$ 的顺序深入，但顺序取决于邻居存放方式。它擅长检查连通性、处理子树和回溯，不保证最短路径。

两种遍历在每个顶点入队或调用一次、每条边检查常数次的实现下，时间均为 $O(n+m)$，额外标记和队列/栈为 $O(n)$。不要等出队才首次标记，否则同一顶点可能重复入队。图不连通时，从一个起点无法覆盖所有点；统计连通块应从每个尚未访问点再启动一次遍历。树的深递归可能用尽调用栈。

### 从零讲：vector：长度可变的连续数组

`vector<T>` 保存一串同类型的元素，适合按下标访问、扫描、排序。`T` 是元素类型，例如 `vector<int>` 保存整数，`vector<pair<int,int>>` 保存整数对，`vector<vector<int>>` 可保存每个顶点各自的邻居。需要 `<vector>`。

```cxx
vector<int> a(3, 7);   // 三个元素，内容是 7、7、7
a.push_back(9);       // 在末尾追加，现在长度为 4
int x = a[1];         // 从 0 编号，这里得到 7
a[1] = 2;            // 改第二个元素
int n = int(a.size());
```

`vector<int> a(3)` 创建三个值为零的元素；`a.reserve(3)` 只预留容量，元素数仍为零，此时不能访问 `a[0]`。长度 `size()` 与容量 `capacity()` 是不同概念。

下标访问为 $O(1)$，遍历为 $O(n)$。末尾追加通常为 $O(1)$；容量不足时会分配更大的连续空间并搬移元素，这次可能为 $O(n)$，一连串追加的平均成本称为摊还 $O(1)$。中间插入或删除会搬移后续元素，最坏 $O(n)$。内存是元素量的 $O(n)$，并可能预留部分尚未使用的容量。

`begin()` 指向首元素，`end()` 指向尾后位置，`sort(a.begin(),a.end())` 操作整个数组。`a[i]` 不检查越界；下标须满足 $0\le i<\mathrm{size}$。`at(i)` 会检查越界并抛异常。空数组不能访问 `front()`、`back()`；`pop_back()` 也要求非空。

扩容后指向旧存储的迭代器、引用和指针会失效。遍历的同时 `push_back`，不能假定此前取得的引用仍可用。读取大数组的函数常用 `const vector<int>& a` 按常量引用传入，既不复制也禁止通过该引用修改；`vector<int> a` 按值传参则复制内容。选择副本还是引用取决于是否要保留独立数据。

### 从零讲：pair、tuple 与结构化绑定

有些数据天然需要成组：一个区间有两个端点，一个队列状态有坐标和距离。`pair<A,B>` 保存两项，用 `.first`、`.second` 读取；`tuple<A,B,C>` 可保存更多项，用 `get<0>(t)` 等读取。分别需要 `<utility>`、`<tuple>`。

C++17 的结构化绑定能为一组分量起局部名字：

```cxx
pair<int,int> point{3, 5};
auto [x, y] = point;      // 复制出两个分量
x = 9;                  // point.first 仍为 3
auto& [u, v] = point;    // 绑定原对象的分量
u = 7;                  // point.first 变为 7
```

`for (auto [l,r] : segments)` 每轮读取一对值；`for (const auto& [l,r] : segments)` 以只读引用读取，避免复制；需要修改原记录时才用 `auto&`。引用必须在原对象还存在且位置未失效时使用。

`pair` 和 `tuple` 的默认比较是字典序：从第一项起，第一个不同的分量决定顺序。`priority_queue<pair<int,int>>` 因而先比较第一项，再以第二项破同分，不能误认为只看第一项。这类语法只让记录组织和访问更清楚，拆分本身的成本取决于分量是否需要复制。

### 从零讲：queue、deque 与 stack：处理顺序也是规则

`queue` 是先进先出：先进入的先处理，适合按层扩展；`stack` 是后进先出：最后放入的先处理，适合嵌套配对与回退；`deque` 支持两端加入删除，适合滑动窗口和 0-1 BFS。它们不能按方便程度随意互换，处理顺序会影响算法成立的理由。

```cxx
queue<int> q;
q.push(3); q.push(5);
int first = q.front(); // 3
q.pop();              // 删除 3，pop 不返回元素
stack<int> st;
st.push(3); st.push(5);
int last = st.top();   // 5
st.pop();
```

`deque` 的接口是 `push_back`、`push_front`、`pop_back`、`pop_front`、`front`、`back`。在常用默认底层容器下，这些端点操作为常数时间；保存 $n$ 项需要 $O(n)$ 空间。`stack` 和 `queue` 是限制了接口的适配器，也可选择其它底层容器。

任何 `front`、`back`、`top` 或弹出操作前都须保证非空；先读元素再弹出。遍历图时，容器只规定“谁先处理”，仍需另存访问标记；若不限制同一个状态反复入队，有限图也可能无限重复处理。

### 从零讲：string：字符、下标与子串

`string` 保存字符序列。`string s="abca";` 的长度为四，下标从零开始，`s[0]=='a'`、`s[3]=='a'`。字符用单引号，字符串用双引号；二者类型不同。需要 `<string>`。

`cin >> s` 读到空白停止；整行含空格时使用 `getline`，并留意前一次格式化输入残留的换行。`s.size()` 是字符单元数量，不一定等于 UTF-8 中文字数；竞赛英文小写字母题通常一个字符对应一个单元。

```cxx
string s = "abca";
string middle = s.substr(1, 2); // 从下标 1 开始取 2 个字符，得到 bc
size_t pos = s.find('c');       // 得到 2；找不到是 string::npos
if (pos != string::npos) cout << s[pos];
```

`substr(start,length)` 的第二项是长度，不是右端点。普通下标访问为 $O(1)$；复制长为 $k$ 的子串需要 $O(k)$ 时间和空间，循环里反复截取可能累积成平方成本。字符串比较按第一个不同字符决定字典序，公共前缀可能需要线性比较。

常见字符转数字是 `c-'0'`，前提 `c` 在 `'0'` 到 `'9'`。修改原串可用 `for(char& c:s)`，只读使用 `char c`。`reverse(s.begin(),s.end())` 原地翻转；若还需要原串，应先复制。空串不能访问首尾，尾后位置不能当普通字符读取。

<!-- reusable-foundations:end -->

### 思路

给地图补一圈海水，从外侧海水开始，按八个方向遍历海水，标记能够与外海相通的位置。再按四个方向遍历每个陆地连通块，若其中至少一个格子八方向相邻的位置被标记为外海，就计入答案。

海水使用八方向，是因为仅斜角接触的陆地没有形成四方向闭环，海水应能从这个缺口通过。封闭陆地环内的海水无法从外面到达，内层岛屿也不会接触外海。时间、空间复杂度均为 $O(MN)$。

### 同样像被围住，为什么两张原图的答案不同

下图直接使用官方两张地图，绿色是外层陆地A，橙色是其它四连通陆地块；空格均为海水。第一张中B确实被A的一条上下左右闭环包住；第二张中A与B只有角接触，不能一起冒充A自己的闭环。

![两张官方实际地图，闭环内B不计数，第二张海水从左边缺口斜穿A与B的角后到达内部，两小岛都暴露于外海](assets/editorial-reasoning/core14-island-ocean.svg)

第二张第三行第一列是海水，从地图左侧外海可直接进入；再斜走到第二行第二列，便从A、B两个陆地角之间穿过。随后沿第二行的海水向右，能来到C旁边。所以三个陆地块都接触外海，答案是三；若海水只准四方向，就会被这次角接触误挡住。第一张的内湖没有这样的出口，B周围没有外海标记，答案才是一。

这里使用的是互补的两种连接：陆地只有四方向边能组成题目所说的环，而海水八方向移动不能穿过这种环的一条边，也不能经过环上的陆地格。反过来，若一片海水被封住，沿它与外界之间的陆地边界走一圈，就能得到封住它的四方向陆地环；角上存在海水斜通道的地方无法闭合这条边界。不是“图上看着四周有一”便算子岛，围墙必须来自同一座四连通岛屿的真实闭环。

补出的全零边框把整个无限外海接成同一片，从(0,0)搜一次就足以覆盖所有出口；内部湖泊不能另开起点。遍历一个陆地块时，某格旁边发现外海只设置一次布尔值，仍继续搜完整块，最后才 `answer += touchesOcean`。这统计的是岛屿身份，不是接触海水的次数；每块在入队前标seen，不会被后续扫描再次起算。

原陆地格下标始终在一到M、一到N，检查九宫格最多到补框的零到M+1、零到N+1，因此这次读取安全。九宫格中a=b=0检查的是自身，它是陆地，outside必为假；海水搜索中自身也早已标记，不能再次入队。这两个自身方向都是多余但无害的检查，不能把它当成第九条通道。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int tests; cin >> tests;
    const int dx[4] = {-1,1,0,0}, dy[4] = {0,0,-1,1};
    while (tests--) {
        int m,n; cin >> m >> n;
        vector<string> grid(m + 2, string(n + 2, '0'));
        for (int i = 1; i <= m; ++i) {
            string row; cin >> row;
            for (int j = 1; j <= n; ++j) grid[i][j] = row[j-1];
        }
        vector<vector<char>> outside(m+2,vector<char>(n+2)), seen=outside;
        queue<pair<int,int>> q; q.push({0,0}); outside[0][0] = true;
        while (!q.empty()) {
            auto [x,y] = q.front(); q.pop();
            for (int a = -1; a <= 1; ++a) for (int b = -1; b <= 1; ++b) {
                int u = x+a, v = y+b;
                if (u<0 || u>m+1 || v<0 || v>n+1) continue;
                if (grid[u][v]=='0' && !outside[u][v]) {
                    outside[u][v]=true; q.push({u,v});
                }
            }
        }
        int answer = 0;
        for (int i=1;i<=m;++i) for (int j=1;j<=n;++j) if (grid[i][j]=='1' && !seen[i][j]) {
            bool touchesOcean=false; seen[i][j]=true; q.push({i,j});
            while (!q.empty()) {
                auto [x,y]=q.front(); q.pop();
                for (int a=-1;a<=1;++a) for (int b=-1;b<=1;++b)
                    if (outside[x+a][y+b]) touchesOcean=true;
                for (int d=0;d<4;++d) {
                    int u=x+dx[d],v=y+dy[d];
                    if (grid[u][v]=='1' && !seen[u][v]) {
                        seen[u][v]=true; q.push({u,v});
                    }
                }
            }
            answer += touchesOcean;
        }
        cout << answer << '\n';
    }
}
```

### 易错点

陆地四连通、海水八连通，不能统一成同一种方向。外海搜索只从补出的外圈开始；内部湖泊不能自行成为新起点。

## G. 子串简写

[题目](https://www.luogu.com.cn/problem/P9244)

### 题意

统计字符串中首字符为 $c_1$、尾字符为 $c_2$，且长度至少为 $K$ 的子串数量。

<!-- reusable-foundations:start -->

### 从零讲：前缀和：一段和由两段前缀相减

一串数需要反复询问连续一段的总和，逐段扫描会重复加很多相同元素。先保存从头到每个位置的累计量，就能复用这些工作。

对从一编号的数组定义 $S_0=0$，$S_i=a_1+\cdots+a_i$。例如 $a=[2,3,1,4]$，前缀为 $S=[0,2,5,6,10]$。

![S4 包含整段，S1 是多算的前缀，减去后留下第 2 至 4 项](assets/foundations/prefix.svg)

查询 $[2,4]$ 时，$S_4$ 包含第一个数，减去 $S_1$ 后留下 $3+1+4=8$。一般地，$S_r-S_{l-1}$ 中前 $l-1$ 项逐项抵消，只留下第 $l$ 到第 $r$ 项。

```cxx
vector<long long> s(n + 1, 0);
for (int i = 1; i <= n; ++i) s[i] = s[i - 1] + a[i];
long long sum = s[r] - s[l - 1];
```

预处理 $O(n)$ 时间和空间，每次查询 $O(1)$，比 $q$ 次逐段扫描的最坏 $O(nq)$ 更适合大量静态区间和。若使用从零编号的原数组，也可定义 $P_i$ 为前 $i$ 项之和，查询闭区间 $[l,r]$ 为 $P_{r+1}-P_l$；不要混用两套下标。

前缀可以累积满足条件的次数，把每项变成零或一；也可以保存异或，此时相同前缀通过异或抵消。最小值没有同样的可逆减法，不能直接套区间最小值。原数组改变后，后续许多前缀都受影响；频繁在线修改时可考虑树状数组或线段树。

首个空前缀零不可漏，累加类型要覆盖总和。数学上的减法可能得到负值，别让无符号类型把它变成巨大正数。

### 从零讲：双指针与连续窗口：边界为什么能只向前走

当一段区间的合法性随边界移动有可证明的单调变化，可用两个边界维护连续窗口，避免为每个左端点重新扫描右边。

例如数组元素均非负，求和不超过五的最长子段。对 $[2,1,3,2]$，右端依次扩展；加三后总和六，移走左端二后为四；再加二后为六，再移走一后仍为五，窗口成为 $[3,2]$。每次扩展右端，只向右移动左端直到重新合法。

![右端加入一项，左端按需移走，两个边界都不回退](assets/foundations/two-pointers.svg)

```cxx
int left = 0, best = 0;
long long sum = 0;
for (int right = 0; right < n; ++right) {
    sum += a[right];
    while (left <= right && sum > limit) sum -= a[left++];
    best = max(best, right - left + 1);
}
```

虽然有嵌套循环，左右端各至多移动 $n$ 次，合计为 $O(n)$；维护窗口和用 $O(1)$ 额外空间。证明要数指针总移动次数，不能只看循环嵌套层数。

非负条件使扩展不会降低和，缩短不会增大和。若含负数，当前超限的窗口未来可能因加入负数重新合法，过早丢掉左端可能漏解，需要别的方法。窗口里的最大值也不能像和一样直接相减，要配单调队列等维护结构。

另一类相向双指针在有序数组两端出发，例如找两数和：和太小才移动左边，太大移动右边，依据有序性排除候选。排序会影响原下标和连续性，不能为了套双指针擅自改变题目对象。

### 从零讲：string：字符、下标与子串

`string` 保存字符序列。`string s="abca";` 的长度为四，下标从零开始，`s[0]=='a'`、`s[3]=='a'`。字符用单引号，字符串用双引号；二者类型不同。需要 `<string>`。

`cin >> s` 读到空白停止；整行含空格时使用 `getline`，并留意前一次格式化输入残留的换行。`s.size()` 是字符单元数量，不一定等于 UTF-8 中文字数；竞赛英文小写字母题通常一个字符对应一个单元。

```cxx
string s = "abca";
string middle = s.substr(1, 2); // 从下标 1 开始取 2 个字符，得到 bc
size_t pos = s.find('c');       // 得到 2；找不到是 string::npos
if (pos != string::npos) cout << s[pos];
```

`substr(start,length)` 的第二项是长度，不是右端点。普通下标访问为 $O(1)$；复制长为 $k$ 的子串需要 $O(k)$ 时间和空间，循环里反复截取可能累积成平方成本。字符串比较按第一个不同字符决定字典序，公共前缀可能需要线性比较。

常见字符转数字是 `c-'0'`，前提 `c` 在 `'0'` 到 `'9'`。修改原串可用 `for(char& c:s)`，只读使用 `char c`。`reverse(s.begin(),s.end())` 原地翻转；若还需要原串，应先复制。空串不能访问首尾，尾后位置不能当普通字符读取。

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cxx
int a = 100000, b = 100000;
long long wrong = a * b;      // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

<!-- reusable-foundations:end -->

### 思路

固定右端点 $r$（从 $0$ 开始），合法左端点需满足 $l\le r-K+1$。维护这一前缀中字符 $c_1$ 的数量 $\mathit{count}$，每当右端点右移，就把新获得资格的位置 $r-K+1$ 加入统计。若当前字符为 $c_2$，将 $\mathit{count}$ 加入答案。

每个合法子串都按其唯一右端点计数一次。时间复杂度 $O(|S|)$，除字符串外额外空间 $O(1)$。

### 这次加进去的是左端位置，不是字符种类

在官方例串 `abababdb`、K=4 中，把零基下标与六个实际区间画出来：

![原串八个位置及六条真实子串区间，分别归入右端三五七三个批次](assets/editorial-reasoning/core10-substring-intervals.svg)

右端 r 从三到七时，新取得长度资格的左端依次是零、一、二、三、四，`count` 依次为一、一、二、二、三。r=3 先加入位置零，再认出当前位置是 b，故增加一；r=4 虽把新位置检查过，但当前是 a，不增加答案；r=5 增加二；r=6 是 d，不增加；r=7 增加三，合计六。若先计算答案再加入新位置，会漏掉图中长度恰为四的区间。

在每次判断 `s[r]==b` 时，`count` 恰为所有 $0\le l\le r-K+1$ 且首字符是 a 的位置数：上一次已有的位置保持资格，这次只有最右边的一个位置新取得资格。配上当前的 b 后，每个位置都给出一个长度合格、首尾字符合格的子串，所以加上整个 `count` 已足够；没有别的内部字符限制。任一合法子串又有唯一的有序端点对，恰在自己的右端被访问一次。相同文本位于不同区间仍应分别计数，不能用字符串内容去重。

若首尾目标相同，例如 `aaa`、K=2、都取 a，合法区间是 $[0,1],[0,2],[1,2]$ 三个；同一位置不会自己配自己，因为 $K\ge2$ 始终使 $l<r$。全长五十万且全部是 a、K=2 时有 $n(n-1)/2$ 个，超过32位整数，故两个累计量都用 `long long`。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int k; string s; char a, b;
    cin >> k >> s >> a >> b;
    long long count = 0, answer = 0;
    for (int r = k - 1; r < (int)s.size(); ++r) {
        if (s[r - k + 1] == a) ++count;
        if (s[r] == b) answer += count;
    }
    cout << answer << '\n';
}
```

### 易错点

必须先加入当前新合法的左端点，再计算当前右端点的贡献，否则会漏掉长度恰好为 $K$ 的子串。$c_1=c_2$ 时算法也成立。

## I. 景区导游

[题目](https://www.luogu.com.cn/problem/P9245)

### 题意

按给定顺序游览树上的 $K$ 个景点。对每个位置，求跳过该景点后，相邻保留景点之间的总路程。

<!-- reusable-foundations:start -->

### 从零讲：树的根、子树、DFS 序与倍增

树是连通且无环的无向图，$n$ 个顶点有 $n-1$ 条边。指定一个根后，每个非根顶点有唯一父亲，其他向下邻居是孩子。子树包含自己和全部后代；换根会改变父子关系，但不改变原边。

![同一棵树选定根后，圈出的子树包含节点自己及其全部后代](assets/foundations/trees.svg)

#### 子树信息按依赖顺序计算

例如子树大小 `size[u]` 初始为一，每个孩子处理完后累加 `size[v]`。一来自节点自己，不能漏掉。树形 DP 也如此：先明确某状态允许怎样选择，再合并各孩子提供的信息；孩子独立性来自树上没有跨子树边，仍可能因总预算或选中父亲等条件产生状态关联。

换根 DP 先求一个根的状态，再沿边换根，将“来自孩子的一侧”和“来自父亲的一侧”合并。应画清只有哪条边的方向改变、哪些量不变；不能仅凭两张答案表代替依赖解释。普通遍历每条边常数次为 $O(n)$，背包式合并可能更大，按实际合并循环计算。

#### DFS 序为什么能把子树变成区间

进入节点时分配编号 `tin[u]`，完成整棵子树后记录最后编号 `tout[u]`。深度优先在返回父亲前会完整处理这棵子树，因此它的所有编号连续，恰是 $[tin[u],tout[u]]$。这允许把子树和等查询交给数组结构。若同时记录进出事件，区间定义会不同，不可混用两种序列。

#### 倍增与最近公共祖先

`up[k][u]` 存 $u$ 向上 $2^k$ 条边到达的祖先。基础 `up[0][u]=parent[u]`，递推为 `up[k][u]=up[k-1][up[k-1][u]]`，因为连续走两段 $2^{k-1}$。跳十三层可拆为八加四加一，只需对数个跳跃。

LCA 是两个节点公共祖先中最深者。先把更深的一方跳到同深度；若已经相同就是答案。否则从大到小试跳，祖先不同才两边同时上移，最后它们的父亲就是 LCA。预处理 $O(n\log n)$、每次查询 $O(\log n)$，表空间 $O(n\log n)$。根的虚拟祖先需统一定义，不能访问非法下标。

树的直径在非负无权边长等常见条件下可用两次最远点搜索求出；带负权时要重新判断。虚树则将关注节点按 DFS 序组织，补上相邻节点的 LCA 后连接祖先关系，边应携带原路径含义，不能把压缩后一条边误当原图一步。深链上的递归也须留意栈深度。

### 从零讲：lambda：定义、捕获和调用一个局部函数

#### 它解决什么问题

一段操作在当前函数里需要调用多次，或者某个算法需要你提供“怎样比较”的规则，可以把这段操作写成 lambda。lambda 表达式产生一个可以像函数一样调用的对象；“匿名”指它没有普通函数声明中的函数名，仍可以用变量保存并命名。

```cxx
auto add = [](int a, int b) -> int {
    return a + b;
};
int answer = add(2, 3);  // 调用后得到 5；定义本身不会执行函数体
```

读法是：用 `auto` 保存对象；`[]` 是捕获列表；圆括号是每次调用传入的参数；`-> int` 指定返回类型；花括号里写执行过程；定义后的分号结束赋值。返回类型能够推导时可省略，所以也常见 `auto add = [](int a,int b) { return a+b; };`。

![参数在调用时传入，捕获连接定义位置可见的外部变量](assets/foundations/lambda.svg)

#### 参数和捕获有什么区别

参数每次调用都由调用者提供；捕获让函数体使用定义位置附近的局部变量，调用时不用重复传它。例如阈值来自当前环境，待判断的值每次变化：

```cxx
int threshold = 10;
auto enough = [threshold](int value) {
    return value >= threshold;
};
bool a = enough(12);  // true，value 是本次传入的 12
```

这里 `threshold` 是捕获，`value` 是参数。常用的捕获方式如下：

| 写法 | 意思 | 适合的需要 |
|---|---|---|
| `[]` | 不捕获局部变量 | 只依赖参数的计算或比较 |
| `[x]` | 保存定义时 `x` 的副本 | 需要固定一份快照 |
| `[&x]` | 引用外面的 `x` | 读取最新值或修改原变量 |
| `[=]` | 按值捕获实际需要的局部变量 | 需要多个快照 |
| `[&]` | 按引用捕获实际需要的局部变量 | 当前作用域内的辅助函数 |
| `[&a, limit]` | 引用 `a`，复制 `limit` | 显式区分共享数据和快照 |

`[&]` 不是“把参数按引用传递”；是否按引用传参由圆括号里的 `int&`、`const vector<int>&` 等类型决定。全局变量可以直接访问，无需捕获。

#### 用可观察的结果区分复制与引用

```cxx
int base = 10;
auto snapshot = [base](int x) { return base + x; };
auto current = [&base](int x) { return base + x; };
base = 20;
int a = snapshot(1);  // 11：使用定义时保存的 10
int b = current(1);   // 21：使用外面的最新值 20
```

默认情况下不能在 lambda 内修改按值捕获的副本。加 `mutable` 才能修改副本，但仍不会改外面的原变量：`auto next = [base]() mutable { return ++base; };`。对大数组按值捕获可能复制整个数组；如果只在数组仍然存活时查询，显式引用可避免这份复制。

#### 两种常见用法

**局部辅助函数。** 把“给一个参数就求出结果”的操作命名后，主流程只写调用。外层数组保持原处，辅助函数按引用读取，能减少重复代码，并让环境依赖集中在定义附近。对多个调用位置修正一处逻辑即可。普通独立函数也能做到复用，但外层局部数据通常需要显式传参。

**作为算法的规则。** 把比较方式直接交给 `sort`，能在调用处看到排序依据：

```cxx
sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
    if (a.first != b.first) return a.first < b.first;
    return a.second > b.second;
});
```

先按第一项升序，第一项相同时按第二项降序。比较器必须形成严格弱序，同一个元素与自己比较应为假；写成 `<=` 可能破坏排序前提。传 `const auto&` 可以避免每次比较都复制元素。

#### 递归时怎样引用自己

在 `auto f = ...` 的初始化表达式中不能直接假定 `f` 的类型已确定。C++17 可以把自己作为参数传进去：

```cxx
auto factorial = [](auto&& self, int n) -> long long {
    if (n <= 1) return 1;
    return n * self(self, n - 1);
};
long long value = factorial(factorial, 5);  // 120
```

也可先声明 `std::function<long long(int)> f` 再赋 lambda，通过引用调用 `f`；需要 `<functional>`。`std::function` 用统一类型包装可调用对象，便于存储和传递，但可能有间接调用、分配等额外开销。只在当前地方使用时，`auto` 常更直接。这些是组织代码的选择，不会改变原算法的复杂度。

#### 生命周期和复杂度

引用捕获不会延长被引用变量的生命。把引用局部数组的 lambda 返回到函数外，局部数组已经销毁，再调用就会访问失效对象；放入异步任务或长久保存时，也须检查这一点。必要时捕获一份拥有数据的副本，或设计明确的共享所有权。

调用一次 lambda 的时间取决于函数体：内部扫描 $n$ 个元素就是 $O(n)$，做两次有序数组二分就是 $O(\log n)$。创建时复制大容器还会有与数据量相关的成本。lambda 的优势是局部表达、复用和传递行为，本身不保证运行更快。

规范核对：[C++ 工作草案：捕获](https://eel.is/c++draft/expr.prim.lambda.capture)、[函数对象](https://eel.is/c++draft/function.objects)。示例均为 C++17 写法。

### 从零讲：vector：长度可变的连续数组

`vector<T>` 保存一串同类型的元素，适合按下标访问、扫描、排序。`T` 是元素类型，例如 `vector<int>` 保存整数，`vector<pair<int,int>>` 保存整数对，`vector<vector<int>>` 可保存每个顶点各自的邻居。需要 `<vector>`。

```cxx
vector<int> a(3, 7);   // 三个元素，内容是 7、7、7
a.push_back(9);       // 在末尾追加，现在长度为 4
int x = a[1];         // 从 0 编号，这里得到 7
a[1] = 2;            // 改第二个元素
int n = int(a.size());
```

`vector<int> a(3)` 创建三个值为零的元素；`a.reserve(3)` 只预留容量，元素数仍为零，此时不能访问 `a[0]`。长度 `size()` 与容量 `capacity()` 是不同概念。

下标访问为 $O(1)$，遍历为 $O(n)$。末尾追加通常为 $O(1)$；容量不足时会分配更大的连续空间并搬移元素，这次可能为 $O(n)$，一连串追加的平均成本称为摊还 $O(1)$。中间插入或删除会搬移后续元素，最坏 $O(n)$。内存是元素量的 $O(n)$，并可能预留部分尚未使用的容量。

`begin()` 指向首元素，`end()` 指向尾后位置，`sort(a.begin(),a.end())` 操作整个数组。`a[i]` 不检查越界；下标须满足 $0\le i<\mathrm{size}$。`at(i)` 会检查越界并抛异常。空数组不能访问 `front()`、`back()`；`pop_back()` 也要求非空。

扩容后指向旧存储的迭代器、引用和指针会失效。遍历的同时 `push_back`，不能假定此前取得的引用仍可用。读取大数组的函数常用 `const vector<int>& a` 按常量引用传入，既不复制也禁止通过该引用修改；`vector<int> a` 按值传参则复制内容。选择副本还是引用取决于是否要保留独立数据。

### 从零讲：pair、tuple 与结构化绑定

有些数据天然需要成组：一个区间有两个端点，一个队列状态有坐标和距离。`pair<A,B>` 保存两项，用 `.first`、`.second` 读取；`tuple<A,B,C>` 可保存更多项，用 `get<0>(t)` 等读取。分别需要 `<utility>`、`<tuple>`。

C++17 的结构化绑定能为一组分量起局部名字：

```cxx
pair<int,int> point{3, 5};
auto [x, y] = point;      // 复制出两个分量
x = 9;                  // point.first 仍为 3
auto& [u, v] = point;    // 绑定原对象的分量
u = 7;                  // point.first 变为 7
```

`for (auto [l,r] : segments)` 每轮读取一对值；`for (const auto& [l,r] : segments)` 以只读引用读取，避免复制；需要修改原记录时才用 `auto&`。引用必须在原对象还存在且位置未失效时使用。

`pair` 和 `tuple` 的默认比较是字典序：从第一项起，第一个不同的分量决定顺序。`priority_queue<pair<int,int>>` 因而先比较第一项，再以第二项破同分，不能误认为只看第一项。这类语法只让记录组织和访问更清楚，拆分本身的成本取决于分量是否需要复制。

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cxx
int a = 100000, b = 100000;
long long wrong = a * b;      // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

### 从零讲：位运算：把非负整数看成一组二进制开关

五写成二进制为 $0101_2$，三为 $0011_2$。同一列各代表一位：按位与 `&` 两边都为一才得一，按位或 `|` 任一为一就得一，按位异或 `^` 不同才为一。所以 $5\mathbin{\&}3=1$，$5\mathbin{|}3=7$，$5\mathbin{\oplus}3=6$。

![相同数值分别写成每一位，逐列计算与、或、异或](assets/foundations/bits.svg)

`1ULL << k` 把一移到第 $k$ 位。对非负无符号整数，`(mask >> k) & 1ULL` 读该位，`mask | (1ULL<<k)` 置一，`mask & ~(1ULL<<k)` 清零，`mask ^ (1ULL<<k)` 翻转。最低位编号为零。

```cxx
unsigned long long mask = 5; // 第 0、2 位为一
bool has = (mask >> 2) & 1ULL; // true
mask |= 1ULL << 1;             // 变成 7
```

位移次数必须小于类型位宽，且不能为负；不要用普通 `1` 去移到超出 int 范围的位置。C++17 有符号负数右移和溢出的规则不适合直接套“乘除二的幂”，用明确范围的无符号数更容易保证行为。`^` 是异或，绝不是乘方。

逻辑与 `&&`、逻辑或 `||` 将整体条件视为真假，并会短路；按位 `&`、`|` 逐位计算，不会因此跳过右侧表达式。运算符优先级可能与直觉不同，写 `(mask & bit) != 0`，别省掉关键括号。

固定机器字内的一次位运算按 $O(1)$ 估算；枚举全部 $k$ 位状态仍有 $2^k$ 种，不能因为每次运算快就忽略状态数。`x & (x-1)` 对正无符号数清掉最低的一位；GCC 的 `__builtin_popcountll(x)` 统计一的数量，注意实参位宽与具体编译器支持。

<!-- reusable-foundations:end -->

### 思路

先用倍增求最近公共祖先，支持树上两点距离查询：
$$\operatorname{dist}(u,v)=d_u+d_v-2d_{\operatorname{lca}(u,v)},$$
其中 $d_u$ 是根到 $u$ 的带权距离。原路线总长为 $S=\sum_{i=1}^{K-1}\operatorname{dist}(A_i,A_{i+1})$。

删除内部景点 $A_i$ 时，减去与它相接的两段，再补上连接前后景点的一段。删除首尾景点时只减去一段。总时间 $O((N+K)\log N)$，空间 $O(N\log N)$。

#### 被替换的是行程中的两段，公共树边可以乘车多次

原样例的三个行程段 $2\to6,6\to5,5\to1$ 长为7、7、3，总长17。跳过6时，前两段改成 $2\to5$，最后一段保留。下图在同一原树的两份副本上画出这次替换：左边两段都走过3—4和4—6，因此这两条边的车各乘两次，费用也应加两次。

![原带权树中两段七加七的真实重复行走，改为二到五的新四费用路径，最后一段三不变](assets/editorial-reasoning/proofs12-tour-route-occurrences.svg)

新段 $2-1-3-5$ 费用 $1+1+2=4$，故 $17-7-7+4=7$。扣掉的两项是在原总行程中各出现一次的**段位置**，即使使用了一些相同树边，也不是从边集合里重复扣同一条边。其他段和新桥段可以在时间上依次真正走完，所以这份总和可实现；反过来，每一对相邻保留景点都必须用它们唯一的树路径，任一行程也不能更短，故计算值充分且最优。

“跳过一个景点”只删除必游列表的一项，不会删掉原树顶点或禁止路过。例如跳过最后的1后，仍走 $2\to6\to5$；第一段 $2-1-3-4-6$ 仍经过1，答案14合法。若删首项，原先只有它连到后继的一段应扣；若删末项同理；删内部项才同时存在左右两段和补上的桥段。代码三个条件正好实现这三种真实局部变化，K=2时删任一项只剩一个景点，没有乘车段，答案0。

代码的每个输出重新从原总和开始，跳过第i项和跳过第j项是两份独立方案，不会累计改动游览顺序。倍增使用边数深度来对齐祖先，距离公式使用带权根路程；根到LCA的边被计两次，减掉即可，不像点权题还要补LCA点权。路线长度可达约 $10^{15}$，保留原程序的64位总和。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n, k; cin >> n >> k;
    vector<vector<pair<int,int>>> graph(n + 1);
    for (int i = 1; i < n; ++i) {
        int u, v, w; cin >> u >> v >> w;
        graph[u].push_back({v,w}); graph[v].push_back({u,w});
    }
    int lg = 1; while ((1 << lg) <= n) ++lg;
    vector<vector<int>> up(lg, vector<int>(n + 1));
    vector<int> depth(n + 1), order{1};
    vector<long long> rootDistance(n + 1);
    for (size_t pos = 0; pos < order.size(); ++pos) {
        int u = order[pos];
        for (auto [v,w] : graph[u]) if (v != up[0][u]) {
            up[0][v] = u; depth[v] = depth[u] + 1;
            rootDistance[v] = rootDistance[u] + w; order.push_back(v);
        }
    }
    for (int j = 1; j < lg; ++j)
        for (int u = 1; u <= n; ++u) up[j][u] = up[j-1][up[j-1][u]];
    auto lca = [&](int u, int v) {
        if (depth[u] < depth[v]) swap(u,v);
        int delta = depth[u] - depth[v];
        for (int j = 0; j < lg; ++j) if (delta >> j & 1) u = up[j][u];
        if (u == v) return u;
        for (int j = lg - 1; j >= 0; --j) if (up[j][u] != up[j][v]) {
            u = up[j][u]; v = up[j][v];
        }
        return up[0][u];
    };
    auto distance = [&](int u, int v) {
        return rootDistance[u] + rootDistance[v] - 2 * rootDistance[lca(u,v)];
    };
    vector<int> a(k); for (int &u : a) cin >> u;
    vector<long long> segment(k - 1); long long total = 0;
    for (int i = 0; i + 1 < k; ++i) total += segment[i] = distance(a[i], a[i+1]);
    for (int i = 0; i < k; ++i) {
        long long answer = total;
        if (i) answer -= segment[i-1];
        if (i + 1 < k) answer -= segment[i];
        if (i && i + 1 < k) answer += distance(a[i-1], a[i+1]);
        cout << answer << (i + 1 == k ? '\n' : ' ');
    }
}
```

### 易错点

游览路线的总长度可能超过 $32$ 位整数。深度用于祖先查询，带权距离用于求路程，二者不能混用。

## J. 砍树

[题目](https://www.luogu.com.cn/problem/P9246)

### 题意

在树中删除一条边，使给出的每对点都不连通。若有多条可行边，输出输入编号最大的一条。

<!-- reusable-foundations:start -->

### 从零讲：树的根、子树、DFS 序与倍增

树是连通且无环的无向图，$n$ 个顶点有 $n-1$ 条边。指定一个根后，每个非根顶点有唯一父亲，其他向下邻居是孩子。子树包含自己和全部后代；换根会改变父子关系，但不改变原边。

![同一棵树选定根后，圈出的子树包含节点自己及其全部后代](assets/foundations/trees.svg)

#### 子树信息按依赖顺序计算

例如子树大小 `size[u]` 初始为一，每个孩子处理完后累加 `size[v]`。一来自节点自己，不能漏掉。树形 DP 也如此：先明确某状态允许怎样选择，再合并各孩子提供的信息；孩子独立性来自树上没有跨子树边，仍可能因总预算或选中父亲等条件产生状态关联。

换根 DP 先求一个根的状态，再沿边换根，将“来自孩子的一侧”和“来自父亲的一侧”合并。应画清只有哪条边的方向改变、哪些量不变；不能仅凭两张答案表代替依赖解释。普通遍历每条边常数次为 $O(n)$，背包式合并可能更大，按实际合并循环计算。

#### DFS 序为什么能把子树变成区间

进入节点时分配编号 `tin[u]`，完成整棵子树后记录最后编号 `tout[u]`。深度优先在返回父亲前会完整处理这棵子树，因此它的所有编号连续，恰是 $[tin[u],tout[u]]$。这允许把子树和等查询交给数组结构。若同时记录进出事件，区间定义会不同，不可混用两种序列。

#### 倍增与最近公共祖先

`up[k][u]` 存 $u$ 向上 $2^k$ 条边到达的祖先。基础 `up[0][u]=parent[u]`，递推为 `up[k][u]=up[k-1][up[k-1][u]]`，因为连续走两段 $2^{k-1}$。跳十三层可拆为八加四加一，只需对数个跳跃。

LCA 是两个节点公共祖先中最深者。先把更深的一方跳到同深度；若已经相同就是答案。否则从大到小试跳，祖先不同才两边同时上移，最后它们的父亲就是 LCA。预处理 $O(n\log n)$、每次查询 $O(\log n)$，表空间 $O(n\log n)$。根的虚拟祖先需统一定义，不能访问非法下标。

树的直径在非负无权边长等常见条件下可用两次最远点搜索求出；带负权时要重新判断。虚树则将关注节点按 DFS 序组织，补上相邻节点的 LCA 后连接祖先关系，边应携带原路径含义，不能把压缩后一条边误当原图一步。深链上的递归也须留意栈深度。

### 从零讲：差分：把区间的变化写在两个边界

很多次操作都给一整段加同一个数，最后才需要所有位置的结果。逐项修改会重复扫描；差分只记录“从哪里开始多这一份、从哪里停止”。

定义 $D_1=a_1$，$D_i=a_i-a_{i-1}$。从左累计 $D$ 就能恢复 $a$。给闭区间 $[l,r]$ 加 $v$，仅需 $D_l$ 加 $v$、$D_{r+1}$ 减 $v$：第 $l$ 位开始，前缀多出 $v$；到第 $r+1$ 位，额外的一份被抵消。

![第 2 位开始加三，第 5 位停止；只有第 2 至 4 位被改变](assets/foundations/difference.svg)

例如五个零上给 $[2,4]$ 加三，差分事件为 $[0,3,0,0,-3]$，累计得到 $[0,3,3,3,0]$。两个标记不表示只修改了两个原元素。

```cxx
vector<long long> d(n + 2, 0);
d[l] += v;
d[r + 1] -= v;
long long current = 0;
for (int i = 1; i <= n; ++i) {
    current += d[i];
    // current 是该位置受到的总增量
}
```

$q$ 次区间加与最后恢复共 $O(n+q)$，空间 $O(n)$。如果初始数组非零，可先构造它的差分，或在恢复增量后加回原值。右边界要标在后一位，数组须留出 `n+1`；闭区间和半开区间的停止位置不能混用。

差分适合离线集中恢复。若每次操作后立刻查询任意位置，仅存差分并不能自动做到常数时间，需要动态前缀数据结构。坐标非常大但事件少时，应排序事件或离散化，不能按最大坐标盲目分配数组。

### 从零讲：lambda：定义、捕获和调用一个局部函数

#### 它解决什么问题

一段操作在当前函数里需要调用多次，或者某个算法需要你提供“怎样比较”的规则，可以把这段操作写成 lambda。lambda 表达式产生一个可以像函数一样调用的对象；“匿名”指它没有普通函数声明中的函数名，仍可以用变量保存并命名。

```cxx
auto add = [](int a, int b) -> int {
    return a + b;
};
int answer = add(2, 3);  // 调用后得到 5；定义本身不会执行函数体
```

读法是：用 `auto` 保存对象；`[]` 是捕获列表；圆括号是每次调用传入的参数；`-> int` 指定返回类型；花括号里写执行过程；定义后的分号结束赋值。返回类型能够推导时可省略，所以也常见 `auto add = [](int a,int b) { return a+b; };`。

![参数在调用时传入，捕获连接定义位置可见的外部变量](assets/foundations/lambda.svg)

#### 参数和捕获有什么区别

参数每次调用都由调用者提供；捕获让函数体使用定义位置附近的局部变量，调用时不用重复传它。例如阈值来自当前环境，待判断的值每次变化：

```cxx
int threshold = 10;
auto enough = [threshold](int value) {
    return value >= threshold;
};
bool a = enough(12);  // true，value 是本次传入的 12
```

这里 `threshold` 是捕获，`value` 是参数。常用的捕获方式如下：

| 写法 | 意思 | 适合的需要 |
|---|---|---|
| `[]` | 不捕获局部变量 | 只依赖参数的计算或比较 |
| `[x]` | 保存定义时 `x` 的副本 | 需要固定一份快照 |
| `[&x]` | 引用外面的 `x` | 读取最新值或修改原变量 |
| `[=]` | 按值捕获实际需要的局部变量 | 需要多个快照 |
| `[&]` | 按引用捕获实际需要的局部变量 | 当前作用域内的辅助函数 |
| `[&a, limit]` | 引用 `a`，复制 `limit` | 显式区分共享数据和快照 |

`[&]` 不是“把参数按引用传递”；是否按引用传参由圆括号里的 `int&`、`const vector<int>&` 等类型决定。全局变量可以直接访问，无需捕获。

#### 用可观察的结果区分复制与引用

```cxx
int base = 10;
auto snapshot = [base](int x) { return base + x; };
auto current = [&base](int x) { return base + x; };
base = 20;
int a = snapshot(1);  // 11：使用定义时保存的 10
int b = current(1);   // 21：使用外面的最新值 20
```

默认情况下不能在 lambda 内修改按值捕获的副本。加 `mutable` 才能修改副本，但仍不会改外面的原变量：`auto next = [base]() mutable { return ++base; };`。对大数组按值捕获可能复制整个数组；如果只在数组仍然存活时查询，显式引用可避免这份复制。

#### 两种常见用法

**局部辅助函数。** 把“给一个参数就求出结果”的操作命名后，主流程只写调用。外层数组保持原处，辅助函数按引用读取，能减少重复代码，并让环境依赖集中在定义附近。对多个调用位置修正一处逻辑即可。普通独立函数也能做到复用，但外层局部数据通常需要显式传参。

**作为算法的规则。** 把比较方式直接交给 `sort`，能在调用处看到排序依据：

```cxx
sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
    if (a.first != b.first) return a.first < b.first;
    return a.second > b.second;
});
```

先按第一项升序，第一项相同时按第二项降序。比较器必须形成严格弱序，同一个元素与自己比较应为假；写成 `<=` 可能破坏排序前提。传 `const auto&` 可以避免每次比较都复制元素。

#### 递归时怎样引用自己

在 `auto f = ...` 的初始化表达式中不能直接假定 `f` 的类型已确定。C++17 可以把自己作为参数传进去：

```cxx
auto factorial = [](auto&& self, int n) -> long long {
    if (n <= 1) return 1;
    return n * self(self, n - 1);
};
long long value = factorial(factorial, 5);  // 120
```

也可先声明 `std::function<long long(int)> f` 再赋 lambda，通过引用调用 `f`；需要 `<functional>`。`std::function` 用统一类型包装可调用对象，便于存储和传递，但可能有间接调用、分配等额外开销。只在当前地方使用时，`auto` 常更直接。这些是组织代码的选择，不会改变原算法的复杂度。

#### 生命周期和复杂度

引用捕获不会延长被引用变量的生命。把引用局部数组的 lambda 返回到函数外，局部数组已经销毁，再调用就会访问失效对象；放入异步任务或长久保存时，也须检查这一点。必要时捕获一份拥有数据的副本，或设计明确的共享所有权。

调用一次 lambda 的时间取决于函数体：内部扫描 $n$ 个元素就是 $O(n)$，做两次有序数组二分就是 $O(\log n)$。创建时复制大容器还会有与数据量相关的成本。lambda 的优势是局部表达、复用和传递行为，本身不保证运行更快。

规范核对：[C++ 工作草案：捕获](https://eel.is/c++draft/expr.prim.lambda.capture)、[函数对象](https://eel.is/c++draft/function.objects)。示例均为 C++17 写法。

### 从零讲：vector：长度可变的连续数组

`vector<T>` 保存一串同类型的元素，适合按下标访问、扫描、排序。`T` 是元素类型，例如 `vector<int>` 保存整数，`vector<pair<int,int>>` 保存整数对，`vector<vector<int>>` 可保存每个顶点各自的邻居。需要 `<vector>`。

```cxx
vector<int> a(3, 7);   // 三个元素，内容是 7、7、7
a.push_back(9);       // 在末尾追加，现在长度为 4
int x = a[1];         // 从 0 编号，这里得到 7
a[1] = 2;            // 改第二个元素
int n = int(a.size());
```

`vector<int> a(3)` 创建三个值为零的元素；`a.reserve(3)` 只预留容量，元素数仍为零，此时不能访问 `a[0]`。长度 `size()` 与容量 `capacity()` 是不同概念。

下标访问为 $O(1)$，遍历为 $O(n)$。末尾追加通常为 $O(1)$；容量不足时会分配更大的连续空间并搬移元素，这次可能为 $O(n)$，一连串追加的平均成本称为摊还 $O(1)$。中间插入或删除会搬移后续元素，最坏 $O(n)$。内存是元素量的 $O(n)$，并可能预留部分尚未使用的容量。

`begin()` 指向首元素，`end()` 指向尾后位置，`sort(a.begin(),a.end())` 操作整个数组。`a[i]` 不检查越界；下标须满足 $0\le i<\mathrm{size}$。`at(i)` 会检查越界并抛异常。空数组不能访问 `front()`、`back()`；`pop_back()` 也要求非空。

扩容后指向旧存储的迭代器、引用和指针会失效。遍历的同时 `push_back`，不能假定此前取得的引用仍可用。读取大数组的函数常用 `const vector<int>& a` 按常量引用传入，既不复制也禁止通过该引用修改；`vector<int> a` 按值传参则复制内容。选择副本还是引用取决于是否要保留独立数据。

### 从零讲：pair、tuple 与结构化绑定

有些数据天然需要成组：一个区间有两个端点，一个队列状态有坐标和距离。`pair<A,B>` 保存两项，用 `.first`、`.second` 读取；`tuple<A,B,C>` 可保存更多项，用 `get<0>(t)` 等读取。分别需要 `<utility>`、`<tuple>`。

C++17 的结构化绑定能为一组分量起局部名字：

```cxx
pair<int,int> point{3, 5};
auto [x, y] = point;      // 复制出两个分量
x = 9;                  // point.first 仍为 3
auto& [u, v] = point;    // 绑定原对象的分量
u = 7;                  // point.first 变为 7
```

`for (auto [l,r] : segments)` 每轮读取一对值；`for (const auto& [l,r] : segments)` 以只读引用读取，避免复制；需要修改原记录时才用 `auto&`。引用必须在原对象还存在且位置未失效时使用。

`pair` 和 `tuple` 的默认比较是字典序：从第一项起，第一个不同的分量决定顺序。`priority_queue<pair<int,int>>` 因而先比较第一项，再以第二项破同分，不能误认为只看第一项。这类语法只让记录组织和访问更清楚，拆分本身的成本取决于分量是否需要复制。

### 从零讲：位运算：把非负整数看成一组二进制开关

五写成二进制为 $0101_2$，三为 $0011_2$。同一列各代表一位：按位与 `&` 两边都为一才得一，按位或 `|` 任一为一就得一，按位异或 `^` 不同才为一。所以 $5\mathbin{\&}3=1$，$5\mathbin{|}3=7$，$5\mathbin{\oplus}3=6$。

![相同数值分别写成每一位，逐列计算与、或、异或](assets/foundations/bits.svg)

`1ULL << k` 把一移到第 $k$ 位。对非负无符号整数，`(mask >> k) & 1ULL` 读该位，`mask | (1ULL<<k)` 置一，`mask & ~(1ULL<<k)` 清零，`mask ^ (1ULL<<k)` 翻转。最低位编号为零。

```cxx
unsigned long long mask = 5; // 第 0、2 位为一
bool has = (mask >> 2) & 1ULL; // true
mask |= 1ULL << 1;             // 变成 7
```

位移次数必须小于类型位宽，且不能为负；不要用普通 `1` 去移到超出 int 范围的位置。C++17 有符号负数右移和溢出的规则不适合直接套“乘除二的幂”，用明确范围的无符号数更容易保证行为。`^` 是异或，绝不是乘方。

逻辑与 `&&`、逻辑或 `||` 将整体条件视为真假，并会短路；按位 `&`、`|` 逐位计算，不会因此跳过右侧表达式。运算符优先级可能与直觉不同，写 `(mask & bit) != 0`，别省掉关键括号。

固定机器字内的一次位运算按 $O(1)$ 估算；枚举全部 $k$ 位状态仍有 $2^k$ 种，不能因为每次运算快就忽略状态数。`x & (x-1)` 对正无符号数清掉最低的一位；GCC 的 `__builtin_popcountll(x)` 统计一的数量，注意实参位宽与具体编译器支持。

<!-- reusable-foundations:end -->

### 思路

树上删去一条边能分开 $a,b$，当且仅当这条边在 $a$ 到 $b$ 的唯一路径上。因此需要找被全部 $m$ 条路径覆盖的边。

对每对端点做边差分：$cnt[a]++$、$cnt[b]++$、$cnt[\operatorname{lca}(a,b)]-=2$。再从叶到根汇总，结点 $u$ 的子树和就是连接 $u$ 与父亲的边被覆盖次数。找出次数为 $m$ 的边，取最大编号即可。时间复杂度 $O((n+m)\log n)$，空间复杂度 $O(n\log n)$。

#### 把原样例的两条路径和上传数字放回树上

原样例点对(3,6)、(4,5)的四个端点互异，符合原题的配对约束。两条真实路径为 $3-2-5-6$ 和 $4-3-2-5$，共同经过的恰是输入边号2、4。要找的是同一条边同时截断全部点对，不是为每一对各找一条不同的边。

![六点原样例、初始差分零负四一一一一、实际反序上传与公共边二四的最大编号四](assets/editorial-reasoning/proofs12-tree-cut-difference.svg)

两次LCA均为2，所以原始差分在2为 $-4$，在四个端点各为1。代码的父先子后顺序是1、2、3、5、4、6，反过来处理：6上传1给5，4上传1给3；此后5和3都各含两个端点，总和都是2，分别对应父边4、2；它们再上传到2，恰把 $-4$ 抵消为0，边1没有任何覆盖。程序首次遇到父边4时记录4，后来遇到父边2仍取最大值4，不会把遍历次序当作输入编号。

为何一个汇总数就足以判定同一刀可行？固定一条父边，令U为其孩子一侧的整棵子树。对一对端点：两者都在U外时，LCA也在U外，U内差分贡献为0；恰一个在U内时，LCA必在U外，贡献为1；两者都在U内时，LCA也在U内，贡献为 $1+1-2=0$。所以，每一对点对的差分贡献只能是0或1，1恰好表示它的两个端点分落删边后两侧。因此总和达到m，当且仅当m对全部分开；没有负贡献抵消后冒充“全部”的情况，也没有一条路径对同一边重复贡献两次。删这条真实边便能同时实现全部要求。反过来，任一可行边都被全部m条路径覆盖，其非根孩子汇总数必为m，循环会检查到它，不遗漏。

检查时 `count[u]` 已包含所有孩子的上传结果，才能解释为完整子树和；原始 `count[2]=-4` 并不是某条边的负覆盖次数。根最终总和为0且没有父边，不参与候选。原题还保证全部 $2m$ 个端点互不相同，但这不意味着对应路径不重合；图中共边正是要利用的重合。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n, m; cin >> n >> m;
    vector<vector<pair<int,int>>> graph(n + 1);
    for (int id = 1; id < n; ++id) {
        int u,v; cin >> u >> v;
        graph[u].push_back({v,id}); graph[v].push_back({u,id});
    }
    int lg = 1; while ((1 << lg) <= n) ++lg;
    vector<vector<int>> up(lg, vector<int>(n + 1));
    vector<int> depth(n + 1), parentEdge(n + 1), order{1}, count(n + 1);
    for (size_t pos = 0; pos < order.size(); ++pos) {
        int u = order[pos];
        for (auto [v,id] : graph[u]) if (v != up[0][u]) {
            up[0][v] = u; parentEdge[v] = id; depth[v] = depth[u] + 1;
            order.push_back(v);
        }
    }
    for (int j = 1; j < lg; ++j)
        for (int u = 1; u <= n; ++u) up[j][u] = up[j-1][up[j-1][u]];
    auto lca = [&](int u,int v) {
        if (depth[u] < depth[v]) swap(u,v);
        int delta = depth[u] - depth[v];
        for (int j = 0; j < lg; ++j) if (delta >> j & 1) u = up[j][u];
        if (u == v) return u;
        for (int j = lg - 1; j >= 0; --j) if (up[j][u] != up[j][v]) {
            u = up[j][u]; v = up[j][v];
        }
        return up[0][u];
    };
    for (int query = 0; query < m; ++query) {
        int a,b; cin >> a >> b;
        ++count[a]; ++count[b]; count[lca(a,b)] -= 2;
    }
    int answer = -1;
    for (int pos = n - 1; pos > 0; --pos) {
        int u = order[pos];
        if (count[u] == m) answer = max(answer, parentEdge[u]);
        count[up[0][u]] += count[u]; // 反序处理，所有孩子已经汇总
    }
    cout << answer << '\n';
}
```

### 易错点

这里统计的是边，不是路径上的点，因此在最近公共祖先处减 $2$。答案比较的是输入边编号，不是结点编号；根没有对应父边。

