### 思路

正权保证最优两路径至多相交一个点。交集更长时，可以把交集两侧对应端点分别连成两条互不相交路径，保留原独有点并多计交集端点，更优。

相交一点 $u$ 时，得分是去掉 $u$ 后四个不同方向的最长链之和，取最大的至多四条。互不相交时，总能用一条边分开它们，答案是该边两侧各自的最大点权路径和。

用两遍树形 DP：先求每棵子树的最长向下链、直径，再换根求父方向最长链与子树外直径。向孩子传递时排除它的链和直径，其他孩子的直径也必须传递。排序邻方向信息后能常数取排除后的前两大，总时间 $O(n\log n)$，空间 $O(n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<ll> a(n);
    for (auto &x : a)
        cin >> x;
    vector<vector<int>> graph(n);
    for (int i = 1, u, v; i < n; ++i) {
        cin >> u >> v;
        --u;
        --v;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }
    vector<int> parent(n, -1), order{0};
    for (int i = 0; i < n; ++i) {
        int u = order[i];
        for (int v : graph[u])
            if (v != parent[u]) {
                parent[v] = u;
                order.push_back(v);
            }
    }
    vector<ll> down(n), diameter(n), up(n), outside(n);
    for (int i = n - 1; i >= 0; --i) {
        int u = order[i];
        ll first = 0, second = 0;
        for (int v : graph[u])
            if (parent[v] == u) {
                diameter[u] = max(diameter[u], diameter[v]);
                ll value = down[v];
                if (value > first) {
                    second = first;
                    first = value;
                } else
                    second = max(second, value);
            }
        down[u] = a[u] + first;
        diameter[u] = max(diameter[u], a[u] + first + second);
    }
    ll answer = 0;
    for (int u : order) {
        vector<pair<ll, int>> arms{{up[u], -1}}, paths{{outside[u], -1}};
        for (int v : graph[u])
            if (parent[v] == u) {
                arms.push_back({down[v], v});
                paths.push_back({diameter[v], v});
            }
        sort(arms.rbegin(), arms.rend());
        sort(paths.rbegin(), paths.rend());
        ll intersect = 0;
        for (int i = 0; i < min(4, (int)arms.size()); ++i)
            intersect += arms[i].first;
        answer = max(answer, intersect);
        for (int v : graph[u])
            if (parent[v] == u) {
                ll first = 0, second = 0;
                int taken = 0;
                for (int i = 0; i < min(3, (int)arms.size()); ++i)
                    if (arms[i].second != v) {
                        if (taken++ == 0)
                            first = arms[i].first;
                        else {
                            second = arms[i].first;
                            break;
                        }
                    }
                ll bestOutside = 0;
                for (int i = 0; i < min(2, (int)paths.size()); ++i)
                    if (paths[i].second != v) {
                        bestOutside = paths[i].first;
                        break;
                    }
                up[v] = a[u] + first;
                outside[v] = max(bestOutside, a[u] + first + second);
                answer = max(answer, diameter[v] + outside[v]);
            }
    }
    cout << answer << '\n';
}
```

### 易错点

恰好两条非空路径，单点路径允许，单节点树答案为零。交点本身不计权。换根外部直径要考虑兄弟子树直径，不能只传一条父方向链。排除孩子时用编号，不能只凭权值删除，以免同权方向混淆。

