### 思路

记前缀最高为 $f_i$、后缀最高为 $g_i$、全局最高为 $M$，有 $\max(f_i,g_i)=M$，所以雨水量为

$$\sum_i f_i+\sum_i g_i-nM-\sum_i a_i.$$

一个位置升至 $h$ 后，前缀最高只需将从该位置到首个原前缀最高不小于 $h$ 之前的区间赋值为 $h$。前缀最高单调，可用维护区间最大值与区间和的线段树找这个边界并区间赋值；将数组反向后同样维护后缀最高。每次修改 $O(\log n)$，总时间 $O((n+q)\log n)$、空间 $O(n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
struct PrefixTree {
    int n;
    vector<long long> sum, maximum, lazy;
    PrefixTree(const vector<long long> &values)
        : n((int)values.size() - 1), sum(4 * n + 4), maximum(4 * n + 4), lazy(4 * n + 4, -1) {
        build(1, 1, n, values);
    }
    void pull(int node) {
        sum[node] = sum[node * 2] + sum[node * 2 + 1];
        maximum[node] = max(maximum[node * 2], maximum[node * 2 + 1]);
    }
    void build(int node, int left, int right, const vector<long long> &values) {
        if (left == right) {
            sum[node] = maximum[node] = values[left];
            return;
        }
        int mid = (left + right) / 2;
        build(node * 2, left, mid, values);
        build(node * 2 + 1, mid + 1, right, values);
        pull(node);
    }
    void assign(int node, int left, int right, long long value) {
        sum[node] = value * (right - left + 1);
        maximum[node] = lazy[node] = value;
    }
    void push(int node, int left, int right) {
        if (lazy[node] < 0 || left == right)
            return;
        int mid = (left + right) / 2;
        assign(node * 2, left, mid, lazy[node]);
        assign(node * 2 + 1, mid + 1, right, lazy[node]);
        lazy[node] = -1;
    }
    int first_ge(long long height) {
        if (maximum[1] < height)
            return n + 1;
        int node = 1, left = 1, right = n;
        while (left < right) {
            push(node, left, right);
            int mid = (left + right) / 2;
            if (maximum[node * 2] >= height) {
                node *= 2;
                right = mid;
            } else {
                node = node * 2 + 1;
                left = mid + 1;
            }
        }
        return left;
    }
    void update(int node, int left, int right, int ql, int qr, long long value) {
        if (ql <= left && right <= qr) {
            assign(node, left, right, value);
            return;
        }
        push(node, left, right);
        int mid = (left + right) / 2;
        if (ql <= mid)
            update(node * 2, left, mid, ql, qr, value);
        if (qr > mid)
            update(node * 2 + 1, mid + 1, right, ql, qr, value);
        pull(node);
    }
    void raise_from(int position, long long height) {
        int end = first_ge(height);
        if (position < end)
            update(1, 1, n, position, end - 1, height);
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int n;
        cin >> n;
        vector<long long> a(n + 1), forward(n + 1), backward(n + 1);
        long long total = 0, highest = 0;
        for (int i = 1; i <= n; ++i) {
            cin >> a[i];
            total += a[i];
            highest = max(highest, a[i]);
            forward[i] = max(forward[i - 1], a[i]);
        }
        for (int i = 1; i <= n; ++i)
            backward[i] = max(backward[i - 1], a[n + 1 - i]);
        PrefixTree left(forward), right(backward);
        int q;
        cin >> q;
        while (q--) {
            int x;
            long long delta;
            cin >> x >> delta;
            a[x] += delta;
            total += delta;
            highest = max(highest, a[x]);
            // 反转下标复用前缀最高的维护，得到原数组后缀最高总和。
            left.raise_from(x, a[x]);
            right.raise_from(n + 1 - x, a[x]);
            cout << left.sum[1] + right.sum[1] - 1LL * n * highest - total << '\n';
        }
    }
}
```

### 易错点

修改给的是增加量，不是新高度。区间赋值前先找到原最高值达到新高度的边界；赋值标记要覆盖旧标记。高柱、总和、$nM$ 均须 64 位。

