### 思路

竞赛图出度最大的点一定支配全图。设这样的点为 $u$，其出邻集为 $A$、入邻集为 $B$。若 $B$ 为空，$u$ 是唯一支配点。否则在 $B$ 内找最大出度点 $v$；若 $v$ 并非 $B$ 的全出点，递归在 $B$ 找三个支配点，它们均能通过 $u$ 两步到达 $A$，故也是全图支配点。

若 $v$ 指向 $B$ 中所有其他点，取 $C=\{a\in A:a\to v\}$。$C$ 非空，否则 $v$ 的出度超过 $u$。取 $C$ 内最大出度点 $w$，则 $u,v,w$ 都支配全图。每层的 $B$ 大小至多当前集合一半，总时间 $O(n^2)$、空间 $O(n^2)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
vector<string> edge;
pair<int, int> maximum_degree(const vector<int> &vertices) {
    int best = -1, degree = -1;
    for (int u : vertices) {
        int current = 0;
        for (int v : vertices)
            current += edge[u][v] == '1';
        if (current > degree) {
            degree = current;
            best = u;
        }
    }
    return {best, degree};
}
vector<int> find_three(const vector<int> &vertices) {
    auto [u, degree] = maximum_degree(vertices);
    vector<int> incoming;
    for (int v : vertices)
        if (edge[v][u] == '1')
            incoming.push_back(v);
    if (incoming.empty())
        return {};
    auto [v, inside_degree] = maximum_degree(incoming);
    // 入邻集内的支配点，经 u 两步即可到达集合外。
    if (inside_degree != (int)incoming.size() - 1)
        return find_three(incoming);
    vector<int> third_candidates;
    for (int w : vertices)
        if (edge[u][w] == '1' && edge[w][v] == '1')
            third_candidates.push_back(w);
    int w = maximum_degree(third_candidates).first;
    return {u, v, w};
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    edge.resize(n);
    for (string &s : edge)
        cin >> s;
    vector<int> vertices(n);
    iota(vertices.begin(), vertices.end(), 0);
    auto answer = find_three(vertices);
    if (answer.empty())
        cout << "NOT FOUND\n";
    else
        cout << answer[0] + 1 << ' ' << answer[1] + 1 << ' ' << answer[2] + 1 << '\n';
}
```

### 易错点

出度必须针对当前诱导子图统计。递归返回的三个点直接作为全图答案，不必保留前两点。构造第三点时找的是出邻集内连向第二点的点。输入没有自环。

