### 思路

若可配对，最小值必须和最大值配对，公共和为 $s=\min+\max$；整个多重集合应在映射 $a\mapsto s-a$ 下不变。维护指数哈希

$$H_+=\sum b^{a_i},\qquad H_-=\sum b^{-a_i},$$

以 $H_+=b^sH_-$ 检查这种对称。区间加 $v$ 时，两者分别乘 $b^v,b^{-v}$，可用懒标记线段树维护，同时维护最小值、最大值、元素和。先用 $2\sum a_i=s\cdot\text{长度}$ 排除显然不合法的区间。

代码在素数 $2^{61}-1$ 下取两个随机底数，双哈希降低误判概率；它是有极小碰撞风险的随机算法。更新值范围有限，可预处理四张幂表；查询另做快速幂。时间 $O(V_0+(n+q)\log n+q\log V)$，空间 $O(n+V_0)$，其中 $V_0=200000$，$V$ 是当前最大值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
using ull = unsigned long long;
using ll = long long;
const ull MOD = (1ULL << 61) - 1;
const int MAXV = 200000;
using Hash = array<ull, 4>;
ull addMod(ull a, ull b) {
    ull s = a + b;
    return s >= MOD ? s - MOD : s;
}
ull multiply(ull a, ull b) {
    __uint128_t z = (__uint128_t)a * b;
    ull result = ((ull)z & MOD) + (ull)(z >> 61);
    return result >= MOD ? result - MOD : result;
}
ull power(ull a, ull e) {
    ull result = 1;
    for (; e; e >>= 1, a = multiply(a, a))
        if (e & 1)
            result = multiply(result, a);
    return result;
}
struct Data {
    Hash hash{};
    ll minimum = LLONG_MAX, maximum = LLONG_MIN, sum = 0;
};
Data mergeData(const Data &a, const Data &b) {
    Data result;
    for (int j = 0; j < 4; ++j)
        result.hash[j] = addMod(a.hash[j], b.hash[j]);
    result.minimum = min(a.minimum, b.minimum);
    result.maximum = max(a.maximum, b.maximum);
    result.sum = a.sum + b.sum;
    return result;
}
struct Node {
    Data data;
    Hash factor{1, 1, 1, 1};
    ll addition = 0;
};
struct SegmentTree {
    int n;
    vector<Node> tree;
    array<vector<ull>, 4> powers;
    array<ull, 2> base;
    SegmentTree(const vector<int> &a) : n((int)a.size() - 1), tree(4 * n + 8) {
        random_device rd;
        mt19937_64 generator(((ull)rd() << 32) ^ rd() ^
                             (ull)chrono::steady_clock::now().time_since_epoch().count());
        uniform_int_distribution<ull> choose(2, MOD - 2);
        base = {choose(generator), choose(generator)};
        Hash roots = {base[0], power(base[0], MOD - 2), base[1], power(base[1], MOD - 2)};
        for (int j = 0; j < 4; ++j) {
            powers[j].resize(MAXV + 1);
            powers[j][0] = 1;
            for (int v = 1; v <= MAXV; ++v)
                powers[j][v] = multiply(powers[j][v - 1], roots[j]);
        }
        build(1, 1, n, a);
    }
    void build(int p, int l, int r, const vector<int> &a) {
        if (l == r) {
            for (int j = 0; j < 4; ++j)
                tree[p].data.hash[j] = powers[j][a[l]];
            tree[p].data.minimum = tree[p].data.maximum = tree[p].data.sum = a[l];
            return;
        }
        int middle = (l + r) / 2;
        build(p * 2, l, middle, a);
        build(p * 2 + 1, middle + 1, r, a);
        pull(p);
    }
    void pull(int p) {
        tree[p].data = mergeData(tree[p * 2].data, tree[p * 2 + 1].data);
    }
    void apply(int p, int length, ll value, const Hash &factor) {
        auto &node = tree[p];
        for (int j = 0; j < 4; ++j) {
            node.data.hash[j] = multiply(node.data.hash[j], factor[j]);
            node.factor[j] = multiply(node.factor[j], factor[j]);
        }
        node.data.minimum += value;
        node.data.maximum += value;
        node.data.sum += value * length;
        node.addition += value;
    }
    void push(int p, int l, int r) {
        if (!tree[p].addition)
            return;
        int middle = (l + r) / 2;
        apply(p * 2, middle - l + 1, tree[p].addition, tree[p].factor);
        apply(p * 2 + 1, r - middle, tree[p].addition, tree[p].factor);
        tree[p].addition = 0;
        tree[p].factor = {1, 1, 1, 1};
    }
    void update(int p, int l, int r, int L, int R, int value, const Hash &factor) {
        if (L <= l && r <= R) {
            apply(p, r - l + 1, value, factor);
            return;
        }
        push(p, l, r);
        int middle = (l + r) / 2;
        if (L <= middle)
            update(p * 2, l, middle, L, R, value, factor);
        if (R > middle)
            update(p * 2 + 1, middle + 1, r, L, R, value, factor);
        pull(p);
    }
    void update(int l, int r, int value) {
        if (!value)
            return;
        Hash factor;
        for (int j = 0; j < 4; ++j)
            factor[j] = powers[j][value];
        update(1, 1, n, l, r, value, factor);
    }
    Data query(int p, int l, int r, int L, int R) {
        if (L <= l && r <= R)
            return tree[p].data;
        push(p, l, r);
        int middle = (l + r) / 2;
        if (R <= middle)
            return query(p * 2, l, middle, L, R);
        if (L > middle)
            return query(p * 2 + 1, middle + 1, r, L, R);
        return mergeData(query(p * 2, l, middle, L, R), query(p * 2 + 1, middle + 1, r, L, R));
    }
    bool possible(int l, int r) {
        Data d = query(1, 1, n, l, r);
        ll sumOfPair = d.minimum + d.maximum;
        if (d.sum * 2 != sumOfPair * (r - l + 1LL))
            return false;
        for (int j = 0; j < 2; ++j)
            if (d.hash[j * 2] != multiply(power(base[j], sumOfPair), d.hash[j * 2 + 1]))
                return false;
        return true;
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<int> a(n + 1);
    for (int i = 1; i <= n; ++i)
        cin >> a[i];
    SegmentTree tree(a);
    while (q--) {
        int type, l, r;
        cin >> type >> l >> r;
        if (type == 1) {
            int v;
            cin >> v;
            tree.update(l, r, v);
        } else
            cout << (tree.possible(l, r) ? "YES\n" : "NO\n");
    }
}
```

### 易错点

区间长度保证为偶数，仍要比较出现次数而非不同值集合。负指数使用乘法逆元。懒加数下推时，四个哈希乘法因子必须一起传递并重置。模乘不能直接用六十四位相乘后取模。双哈希仍是概率判定。

参考：[资料 1](https://contest.ucup.ac/contest/1873?v=1)、[资料 2](https://contest.ucup.ac/download.php?id=1873&r=1&type=attachments)。代码与讲解为独立编写。

## L. Z-order Curve

[题目](https://codeforces.com/gym/105632/problem/L)

### 题意

把自然数的二进制偶数位、奇数位分别抽出来作为平面横纵坐标，顺序连线得到 Z 曲线。给定有向片段 $[L,R]$，求平移后与它相同的片段最早从哪个编号开始。$R\le10^{18}$。

<!-- reusable-foundations:start -->

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cxx
int a = 100000, b = 100000;
long long wrong = a * b;      // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

### 从零讲：位运算：把非负整数看成一组二进制开关

五写成二进制为 $0101_2$，三为 $0011_2$。同一列各代表一位：按位与 `&` 两边都为一才得一，按位或 `|` 任一为一就得一，按位异或 `^` 不同才为一。所以 $5\mathbin{\&}3=1$，$5\mathbin{|}3=7$，$5\mathbin{\oplus}3=6$。

![相同数值分别写成每一位，逐列计算与、或、异或](assets/foundations/bits.svg)

`1ULL << k` 把一移到第 $k$ 位。对非负无符号整数，`(mask >> k) & 1ULL` 读该位，`mask | (1ULL<<k)` 置一，`mask & ~(1ULL<<k)` 清零，`mask ^ (1ULL<<k)` 翻转。最低位编号为零。

```cxx
unsigned long long mask = 5; // 第 0、2 位为一
bool has = (mask >> 2) & 1ULL; // true
mask |= 1ULL << 1;             // 变成 7
```

位移次数必须小于类型位宽，且不能为负；不要用普通 `1` 去移到超出 int 范围的位置。C++17 有符号负数右移和溢出的规则不适合直接套“乘除二的幂”，用明确范围的无符号数更容易保证行为。`^` 是异或，绝不是乘方。

逻辑与 `&&`、逻辑或 `||` 将整体条件视为真假，并会短路；按位 `&`、`|` 逐位计算，不会因此跳过右侧表达式。运算符优先级可能与直觉不同，写 `(mask & bit) != 0`，别省掉关键括号。

固定机器字内的一次位运算按 $O(1)$ 估算；枚举全部 $k$ 位状态仍有 $2^k$ 种，不能因为每次运算快就忽略状态数。`x & (x-1)` 对正无符号数清掉最低的一位；GCC 的 `__builtin_popcountll(x)` 统计一的数量，注意实参位宽与具体编译器支持。

<!-- reusable-foundations:end -->

### 思路

从最高位开始比较 $L,R$。相同的高位只决定整个片段的共同平移，可以清掉；遇到第一处不同就停止。设最高不同位为 $p$，答案为

$$L\bmod 2^{p+1}.$$

这处不同位使片段经过一次“进位到第 $p$ 位”的跳跃。相同有向片段必须在相同相对位置出现同样的跳跃，不能再把起点左移到更小编号。用异或求最高不同位，再保留下面的位即可。每组 $O(\log R)$ 时间、$O(1)$ 空间。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
using ull = unsigned long long;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        ull L, R;
        cin >> L >> R;
        ull different = L ^ R, limit = 1;
        while (limit <= different)
            limit <<= 1;
        cout << (L & (limit - 1)) << '\n';
    }
}
```

### 易错点

曲线带方向，不能把反向走或旋转也视为相同。遇到最高不同位就停止，不能继续清掉后面偶然相同的位。用六十四位整数处理掩码和输入。

