### 思路

同一属性的所有限制取交集：左端取最大，右端取最小。若某个交集为空则无解；否则将初值移动到交集内离它最近的点。各属性互不影响，把距离相加即可。时间 $O(n+q)$，空间 $O(n)$；总距离用六十四位整数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        int n, q;
        cin >> n >> q;
        vector<ll> a(n), low(n, 1), high(n, 1000000000);
        for (auto &x : a)
            cin >> x;
        while (q--) {
            int p;
            ll l, r;
            cin >> p >> l >> r;
            --p;
            low[p] = max(low[p], l);
            high[p] = min(high[p], r);
        }
        ll answer = 0;
        bool possible = true;
        for (int i = 0; i < n; ++i) {
            if (low[i] > high[i])
                possible = false;
            else if (a[i] < low[i])
                answer += low[i] - a[i];
            else if (a[i] > high[i])
                answer += a[i] - high[i];
        }
        cout << (possible ? answer : -1) << '\n';
    }
}
```

### 易错点

