逻辑与 `&&`、逻辑或 `||` 将整体条件视为真假，并会短路；按位 `&`、`|` 逐位计算，不会因此跳过右侧表达式。运算符优先级可能与直觉不同，写 `(mask & bit) != 0`，别省掉关键括号。

固定机器字内的一次位运算按 $O(1)$ 估算；枚举全部 $k$ 位状态仍有 $2^k$ 种，不能因为每次运算快就忽略状态数。`x & (x-1)` 对正无符号数清掉最低的一位；GCC 的 `__builtin_popcountll(x)` 统计一的数量，注意实参位宽与具体编译器支持。

<!-- reusable-foundations:end -->

### 思路

按颜色统计它被多少条路径经过。设某色有 $k$ 个位置：

少于约 $\sqrt{nm}$ 个时，按行优先顺序枚举这些位置，令 $f_i$ 为到第 $i$ 个位置前没经过同色格的前缀路径数。用总前缀路径数减去在更早同色格首次出现的路径：

$$f_i=\binom{r_i+c_i}{r_i}-\sum_{j<i,\ r_j\le r_i,\ c_j\le c_i}f_j\binom{r_i-r_j+c_i-c_j}{r_i-r_j}.$$

再乘该位置到终点的任意后缀路径数，累加得到此色贡献，花 $O(k^2)$。

多于阈值时，直接把该色格子禁用，网格 DP 求完全没经过它的路径数，用总路径数减去，花 $O(nm)$。轻色总花费与重色数量相互约束，整体 $O(nm\sqrt{nm})$，空间 $O(nm)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
const int MOD = 998244353, MAXN = 100000;
vector<int> factorial(MAXN + 1), inverseFactorial(MAXN + 1);
int power(int a, int e) {
    int answer = 1;
    for (; e; e >>= 1, a = 1LL * a * a % MOD)
        if (e & 1)
            answer = 1LL * answer * a % MOD;
    return answer;
}
int choose(int n, int k) {
    if (k < 0 || k > n)
        return 0;
    return 1LL * factorial[n] * inverseFactorial[k] % MOD * inverseFactorial[n - k] % MOD;
}
int paths(int dr, int dc) {
    return dr < 0 || dc < 0 ? 0 : choose(dr + dc, dr);
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    factorial[0] = 1;
    for (int i = 1; i <= MAXN; ++i)
        factorial[i] = 1LL * factorial[i - 1] * i % MOD;
    inverseFactorial[MAXN] = power(factorial[MAXN], MOD - 2);
    for (int i = MAXN; i > 0; --i)
        inverseFactorial[i - 1] = 1LL * inverseFactorial[i] * i % MOD;
    int T;
    cin >> T;
    while (T--) {
        int n, m;
        cin >> n >> m;
        int N = n * m;
        vector<int> grid(N);
        vector<vector<pair<int, int>>> positions(N + 1);
        for (int r = 0; r < n; ++r)
            for (int c = 0; c < m; ++c) {
                int &color = grid[r * m + c];
                cin >> color;
                positions[color].push_back({r, c});
            }
        int threshold = max(1, (int)sqrt(N)), total = paths(n - 1, m - 1), answer = 0;
        for (int color = 1; color <= N; ++color) {
            const auto &p = positions[color];
            if (p.empty())
                continue;
            int contribution = 0;
            if ((int)p.size() <= threshold) {
                vector<int> first(p.size());
                for (int i = 0; i < (int)p.size(); ++i) {
                    auto [r, c] = p[i];
                    int value = paths(r, c);
                    for (int j = 0; j < i; ++j)
                        if (first[j] && p[j].second <= c) {
                            int remove =
                                1LL * first[j] * paths(r - p[j].first, c - p[j].second) % MOD;
                            value -= remove;
                            if (value < 0)
                                value += MOD;
                        }
                    first[i] = value;
                    contribution =
                        (contribution + 1LL * value * paths(n - 1 - r, m - 1 - c)) % MOD;
                }
            } else {
                vector<int> dp(m);
                for (int r = 0; r < n; ++r)
                    for (int c = 0; c < m; ++c) {
                        if (grid[r * m + c] == color)
                            dp[c] = 0;
                        else if (r == 0 && c == 0)
                            dp[c] = 1;
                        else if (c) {
                            dp[c] += dp[c - 1];
                            if (dp[c] >= MOD)
                                dp[c] -= MOD;
                        }
                    }
                contribution = total - dp[m - 1];
                if (contribution < 0)
                    contribution += MOD;
            }
            answer += contribution;
            if (answer >= MOD)
                answer -= MOD;
        }
        cout << answer << '\n';
    }
}
```

### 易错点

按格子直接加路径数会重复计算同色。轻色情况按第一次同色位置归属，后缀不用避障。重色 DP 要阻止起点和终点的该色。阈值按格数而非行数，组合数坐标使用同一套零起点编号。

