            --v;
            edges[e] = {u, v};
            adj[u].push_back({v, e});
            adj[v].push_back({u, e});
            if ((u == x && v == y) || (u == y && v == x))
                initial = e;
        }
        vector<pair<int, int>> direction(m, {-1, -1});
        auto set_direction = [&](int e, int u, int v) { direction[e] = {u, v}; };
        if (initial == -1) {
            for (int e = 0; e < m; ++e) {
                auto [u, v] = edges[e];
                if (u == x || u == y)
                    swap(u, v);
                set_direction(e, u, v);
            }
        } else {
            if (m == n - 1) {
                cout << "No\n";
                continue;
            }
            auto alternate_path = [&](int blocked, int source, int target) {
                vector<int> parent(n, -1);
                queue<int> q;
                q.push(source);
                parent[source] = source;
                while (!q.empty() && parent[target] == -1) {
                    int u = q.front();
                    q.pop();
                    for (auto [v, e] : adj[u])
                        if (e != blocked && parent[v] == -1) {
                            parent[v] = u;
                            q.push(v);
                        }
                }
                vector<int> path;
                if (parent[target] == -1)
                    return path;
                for (int u = target;; u = parent[u]) {
                    path.push_back(u);
                    if (u == source)
                        break;
                }
                reverse(path.begin(), path.end());
                return path;
            };
            vector<int> cycle = alternate_path(initial, x, y);
            vector<int> parent(n, -1), parent_edge(n, -1);
            int anchor = -1;
            if (cycle.empty()) {
                vector<bool> checked(m), seen(n);
                checked[initial] = true;
                queue<int> q;
                q.push(x);
                q.push(y);
                seen[x] = seen[y] = true;
                while (cycle.empty()) {
                    int u = q.front();
                    q.pop();
                    for (auto [v, e] : adj[u])
                        if (!checked[e]) {
                            checked[e] = true;
                            cycle = alternate_path(e, u, v);
                            if (!cycle.empty()) {
                                anchor = u;
                                break;
                            }
                            if (!seen[v]) {
                                seen[v] = true;
                                parent[v] = u;
                                parent_edge[v] = e;
                                q.push(v);
                            }
                        }
                }
            }
            vector<bool> inside(n);
            for (int u : cycle)
                inside[u] = true;
            auto orient_pair = [&](int u, int v) {
                for (auto [w, e] : adj[u])
                    if (w == v) {
                        set_direction(e, u, v);
                        return;
                    }
            };
            for (int i = 0; i < (int)cycle.size(); ++i)
                orient_pair(cycle[i], cycle[(i + 1) % cycle.size()]);
            if (anchor != -1) {
                int u = anchor;
                while (parent[u] != -1) {
                    int p = parent[u];
                    inside[p] = true;
                    set_direction(parent_edge[u], p, u);
                    u = p;
                }
                int other = u == x ? y : x;
                inside[other] = true;
                set_direction(initial, other, u);
            }
            for (int e = 0; e < m; ++e)
                if (direction[e].first == -1) {
                    auto [u, v] = edges[e];
                    // 受控通道与无弦环没有剩余内部边；其余接触边全部朝内。
                    assert(!(inside[u] && inside[v]));
                    if (inside[u])
                        swap(u, v);
                    set_direction(e, u, v);
                }
        }
        cout << "Yes\n";
        for (auto [u, v] : direction)
            cout << u + 1 << ' ' << v + 1 << '\n';
    }
}
```

### 易错点

起点不相邻时，即使图是树也有解。找环要删一条边后的最短路，任意 DFS 环可能有弦。通道外的边要朝通道内部，不能给通道上的人额外出口。只有轮末在同一点才算相遇。

