### 思路

把日期转为从公元一年起累计的天数，再用目标减输入。年份之前的天数为 $365(y-1)+\lfloor(y-1)/4\rfloor-\lfloor(y-1)/100\rfloor+\lfloor(y-1)/400\rfloor$，加上本年此前月份与当月日期即可。最多处理十二个月，时间、空间均为 $O(1)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
bool leap(int y) {
    return y % 400 == 0 || (y % 4 == 0 && y % 100 != 0);
}
long long ordinal(int y, int m, int d) {
    int days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    long long previous = y - 1,
              answer = 365 * previous + previous / 4 - previous / 100 + previous / 400 + d;
    for (int month = 1; month < m; ++month)
        answer += days[month - 1] + (month == 2 && leap(y));
    return answer;
}
int main() {
    int y, m, d;
    cin >> y >> m >> d;
    cout << ordinal(2025, 9, 18) - ordinal(y, m, d) << '\n';
}
```

