### 思路

设根点权为 $x$，沿边 $u-v$ 有 $b_v=w_{uv}-b_u$，所以每个点都形如 $s_vx+c_v$，其中符号 $s_v$ 为正一或负一。

每个点的 $1\le b_v\le10^9$ 都转成对 $x$ 的一个闭区间。将它们取交集，空则无解；否则任选整数 $x$，代回所有点权即可。用迭代遍历传播符号与常数，时间、空间均为 $O(n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<pair<int, ll>>> graph(n);
    for (int i = 1, u, v; i < n; ++i) {
        ll w;
        cin >> u >> v >> w;
        --u;
        --v;
        graph[u].push_back({v, w});
        graph[v].push_back({u, w});
    }
    vector<int> parent(n, -1), sign(n, 1), order{0};
    vector<ll> offset(n);
    for (int i = 0; i < n; ++i) {
        int u = order[i];
        for (auto [v, w] : graph[u])
            if (v != parent[u]) {
                parent[v] = u;
                sign[v] = -sign[u];
                offset[v] = w - offset[u];
                order.push_back(v);
            }
    }
    ll low = 1, high = 1000000000;
    for (int u = 0; u < n; ++u)
        if (sign[u] == 1) {
            low = max(low, 1 - offset[u]);
            high = min(high, 1000000000 - offset[u]);
        } else {
            low = max(low, offset[u] - 1000000000);
            high = min(high, offset[u] - 1);
        }
    if (low > high) {
        cout << "NO\n";
        return 0;
    }
    cout << "YES\n";
    for (int u = 0; u < n; ++u)
        cout << sign[u] * low + offset[u] << (u + 1 == n ? '\n' : ' ');
}
```

### 易错点

点权严格为正，不能允许零。负号的约束方向要正确。中间常数可超过十亿，不能提前截断。单节点树没有边，任取一至十亿的点权都合法。

