### 思路

载客上升的总电量固定，只需减少空载上升。先让电梯逐步到达所有终点的最高层：在起点不高于当前楼层的未处理乘客中，选终点最高且能继续上升的人；若无人能继续上升，就空载到剩余的最小起点。终点不高于已到达高度的人暂时留下。

按起点排序后，每轮扫描全部新可用的乘客，只保留终点最高者作为本轮运送，其余人终点都不超过这轮到达的高度，可留到最后。到达最高层后，剩下的人按终点递减运送，取人途中均只会下降，不再空载上升。时间 $O(n\log n)$、空间 $O(n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
struct Person {
    long long l, r;
    int id;
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int n;
        long long start;
        cin >> n >> start;
        vector<Person> a(n);
        for (int i = 0; i < n; ++i) {
            cin >> a[i].l >> a[i].r;
            a[i].id = i;
        }
        vector<int> by_left(n), by_right(n), order;
        vector<bool> used(n);
        iota(by_left.begin(), by_left.end(), 0);
        by_right = by_left;
        sort(by_left.begin(), by_left.end(), [&](int x, int y) { return a[x].l < a[y].l; });
        long long height = start;
        int at = 0;
        while (at < n) {
            height = max(height, a[by_left[at]].l);
            int best = -1;
            while (at < n && a[by_left[at]].l <= height) {
                int u = by_left[at++];
                if (a[u].r > height && (best < 0 || a[u].r > a[best].r))
                    best = u;
            }
            // 同轮其余乘客终点都不超过新的高度，可留到下降阶段。
            if (best >= 0) {
                used[best] = true;
                order.push_back(best);
                height = a[best].r;
            }
        }
        sort(by_right.begin(), by_right.end(), [&](int x, int y) { return a[x].r > a[y].r; });
        for (int u : by_right)
            if (!used[u])
                order.push_back(u);
        long long energy = 0, current = start;
        for (int u : order) {
            energy += max(a[u].l - current, 0LL) + a[u].r - a[u].l;
            current = a[u].r;
        }
        cout << energy << '\n';
        for (int i = 0; i < n; ++i)
            cout << order[i] + 1 << (i + 1 == n ? '\n' : ' ');
    }
}
```

### 易错点

已经位于某人的起点上方时，可免费下降接人，不必立即服务所有可用乘客。最后输出的耗电必须与实际排列对应，累计值可超过 32 位。

