`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

<!-- reusable-foundations:end -->

### 思路

以第一份榜单的位置为编号，加入其从前到后的链。若另一榜单的某对相邻编号为 $a>b$，这条反向边与第一榜单的链形成环，因此整个区间 $[b,a]$ 都互相可达。合并所有重叠的这种区间，就得到全部强连通块。

每个块在所有榜单中都连续出现，且块的先后顺序相同，所以它们占据的排名区间也相同。询问的榜单编号不影响计数，只需对排名区间求各块内部的配对数。维护前缀配对数，扣除跨过询问左端点的同块配对，即可 $O(1)$ 回答。总时间 $O(nk+q)$、空间 $O(n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int n, k, q;
        cin >> n >> k >> q;
        vector<int> position(n + 1), reach(n + 1);
        iota(reach.begin(), reach.end(), 0);
        for (int i = 1; i <= n; ++i) {
            int u;
            cin >> u;
            position[u] = i;
        }
        for (int row = 1; row < k; ++row) {
            int previous = 0;
            for (int i = 1; i <= n; ++i) {
                int u;
                cin >> u;
                int current = position[u];
                if (previous > current)
                    reach[current] = max(reach[current], previous);
                previous = current;
            }
        }
        vector<int> left(n + 1), right(n + 1);
        vector<long long> prefix(n + 1);
        int end = 0, start = 1;
        for (int i = 1; i <= n; ++i) {
            end = max(end, reach[i]);
            if (i == end) {
                for (int j = start; j <= end; ++j) {
                    left[j] = start;
                    right[j] = end;
                }
                start = i + 1;
            }
        }
        for (int i = 1; i <= n; ++i)
            prefix[i] = prefix[i - 1] + i - left[i];
        long long last = 0;
        while (q--) {
            long long encoded_id, a, b;
            cin >> encoded_id >> a >> b;
            int l = (a + last) % n + 1, r = (b + last) % n + 1;
            // 各榜单的强连通块占据相同排名区间，榜单编号不影响此计数。
            last = prefix[r] - prefix[l - 1] - 1LL * (l - left[l]) * (min(r, right[l]) - l + 1);
            cout << last << '\n';
        }
    }
}
```

