// 题意：给一个长度恰好为 3 的字符串，在每个字符的间隔里插入一个 '.'。
// 做法：字符串长度固定，直接按 字符.字符.字符 的形式输出，时间和空间都是常数。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;                                   // 长度固定为 3，只含字母与数字
