### 从零讲：两颗水果怎么「错车」

在一条链上，两个水果的先后次序不能改变，因为它们不能占同一点，也不能一步跨过对方。互换必须借助度至少三的岔路，让一个水果先离开通道。

![内部岔点的三段移动过程](assets/g-pass.svg)

若岔点在路径内部，一条空支路就够：A 先停到支路，B 走到 A 的原位，A 再走到 B 的原位。若岔点位于端点或端点外，原通道同一侧挤着两个水果，需要岔点的两条空支路先后存放，才能在恢复两个最终位置时互不阻挡。这解释了两种公式中额外二步与四步的区别。

### 思路

记起点距离为 $d$。若两点之间的路径内部有度至少三的岔点，可让一个水果在旁支暂存，另一个通过，再取回暂存者，总步数 $2d+2$。两水果各需走原距离，旁支必须进出一次，所以这个值也是下界。

若内部没有岔点，只能向某个端点外延寻找岔点。设从端点沿不朝向另一水果的方向走到最近岔点的距离为 $t$，端点自己是岔点则 $t=0$。两个水果都必须沿这段外延通道往返，额外 $4t$；在岔点的两条空支路分别暂存一次，共另加四步，故答案为 $2d+4t+4$。两端取较小 $t$，都不存在则无解。

预处理根到每点的岔点数量，配合最近公共祖先可判断路径内部是否有岔点并求 $d$。另做两遍树 DP，记录每点各方向到最近岔点的距离，只保留最小和次小及其方向。询问时排除朝向对方的那个邻居方向，常数时间得到候选 $t$。

预处理 $O(n\log n)$，每问 $O(\log n)$，空间 $O(n\log n)$。

### 参考代码

```cpp
// G. 小橙交换水果
// 结论（小树全枚举 BFS 验证过，见 _work/g_formula_check.py）：
//   记 P = u..v 的唯一路径，d = 路径边数；«换乘点» = 度数 >= 3 的结点（能在它旁边"让车"）。
//   1) 路径中间（不含两端）有换乘点：只需一颗水果在它旁边让一下
//        -> 2d + 2
//   2) 否则换乘点只在两端之外：两颗水果都要绕到那个换乘点，再各自回来
//        t = min(u 端背对路径方向最近换乘点的距离, v 端同理)   -> 2d + 4 + 4t
//   3) 整棵树就是一条链（没有换乘点）  -> -1
// 预处理：LCA（倍增）+ 各方向「最近换乘点距离」(down/up 两遍 DFS) + 路径上换乘点个数（前缀和）。
#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;                                  // n, q <= 2*10^5
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int x, y;
        cin >> x >> y;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }
    vector<int> deg(n + 1);
    for (int i = 1; i <= n; i++) deg[i] = (int)adj[i].size();
    auto isHub = [&](int x) { return deg[x] >= 3; };   // «换乘点»：度数 >= 3

    // ---- 1. 迭代 DFS 定根（1 号点为根）：parent / depth / 访问序 ----
    vector<int> par(n + 1, 0), dep(n + 1, 0), order;
    order.reserve(n);
    {
        vector<char> vis(n + 1, 0);
        vector<int> st;
        st.push_back(1);
        vis[1] = 1;
        while (!st.empty()) {
            int x = st.back();
            st.pop_back();
            order.push_back(x);
            for (int y : adj[x])
                if (!vis[y]) { vis[y] = 1; par[y] = x; dep[y] = dep[x] + 1; st.push_back(y); }
        }
    }

    // ---- 2. 倍增 LCA 表 ----
    int K = 1;
    while ((1 << K) <= n) K++;
    vector<vector<int>> up(K, vector<int>(n + 1, 0));
    for (int i = 1; i <= n; i++) up[0][i] = par[i];
    for (int k = 1; k < K; k++)
        for (int i = 1; i <= n; i++) up[k][i] = up[k - 1][up[k - 1][i]];
    auto lca = [&](int a, int b) {
        if (dep[a] < dep[b]) swap(a, b);
        int diff = dep[a] - dep[b];
        for (int k = 0; k < K; k++) if ((diff >> k) & 1) a = up[k][a];
        if (a == b) return a;
        for (int k = K - 1; k >= 0; k--)
            if (up[k][a] != up[k][b]) { a = up[k][a]; b = up[k][b]; }
        return par[a];
    };
    // 把 a 往上提 diff 层
    auto jump = [&](int a, int diff) {
        for (int k = 0; k < K; k++) if ((diff >> k) & 1) a = up[k][a];
        return a;
    };

    // ---- 3. 根到每个点的「换乘点个数」前缀 ----
    vector<int> cnt3(n + 1, 0);
    for (int x : order) cnt3[x] = cnt3[par[x]] + (isHub(x) ? 1 : 0);

    // ---- 4. down[x]：x 子树内最近换乘点的距离（x 自己是换乘点则为 0）----
    vector<int> down(n + 1, INF);
    for (int idx = n - 1; idx >= 0; idx--) {
        int x = order[idx];
        if (isHub(x)) { down[x] = 0; continue; }
        for (int y : adj[x])
            if (y != par[x] && down[y] + 1 < down[x]) down[x] = down[y] + 1;
    }
    // ---- 5. out[x]：x 子树外最近换乘点、从 x 出发的距离 ----
    // 先给每个点备好「两个最小的 (1 + down[子结点])」，避免在星形图上退化成 O(n^2)
    vector<int> cm1(n + 1, INF), ca1(n + 1, 0), cm2(n + 1, INF);
    for (int x = 1; x <= n; x++)
        for (int y : adj[x])
            if (y != par[x]) {
                int val = (down[y] >= INF) ? INF : down[y] + 1;
                if (val < cm1[x]) { cm2[x] = cm1[x]; cm1[x] = val; ca1[x] = y; }
                else if (val < cm2[x]) cm2[x] = val;
            }
    vector<int> out(n + 1, INF);
    for (int x : order) {                            // 先序：父算完再算子
        if (x == 1) continue;
        int p = par[x];
        int sib = (ca1[p] == x) ? cm2[p] : cm1[p];   // 兄弟子树里的换乘点（离 p 的距离）
        int best = isHub(p) ? 0 : out[p];            // 父亲自己是换乘点 / 继续往上
        best = min(best, sib);
        out[x] = (best >= INF) ? INF : best + 1;
    }
    // ---- 6. 每个点「除某个邻居外」最小的 1 + 该方向最近换乘点距离 ----
    // 方向值：子结点 c -> 1 + down[c]；父结点 -> out[x]
    vector<int> m1(n + 1, INF), a1(n + 1, 0), m2(n + 1, INF);
    for (int x = 1; x <= n; x++) {
        vector<pair<int, int>> cand;
        if (x != 1) cand.push_back({out[x], par[x]});           // 往父结点方向
        for (int y : adj[x])
            if (y != par[x]) cand.push_back({down[y] >= INF ? INF : down[y] + 1, y});
        for (auto& pr : cand) {
            if (pr.first < m1[x]) { m2[x] = m1[x]; m1[x] = pr.first; a1[x] = pr.second; }
            else if (pr.first < m2[x]) m2[x] = pr.first;
        }
    }
    // 排除邻居 excl 之后的最小方向值
    auto minExcept = [&](int x, int excl) {
        return (a1[x] == excl) ? m2[x] : m1[x];
    };

    // ---- 7. 逐问回答 ----
    string buf;
    buf.reserve((size_t)q * 8);
    while (q--) {
        int u, v;
        cin >> u >> v;                               // u != v
        int w = lca(u, v);
        int d = dep[u] + dep[v] - 2 * dep[w];
        int p1 = (w != u) ? par[u] : jump(v, dep[v] - dep[u] - 1);   // u 走向 v 的第一步
        int p2 = (w != v) ? par[v] : jump(u, dep[u] - dep[v] - 1);   // v 走向 u 的第一步
        int onPath = cnt3[u] + cnt3[v] - 2 * cnt3[w] + (isHub(w) ? 1 : 0); // 路径上换乘点个数（含两端）
        int inner = onPath - (isHub(u) ? 1 : 0) - (isHub(v) ? 1 : 0);
        long long ans;
        if (d >= 2 && inner > 0) {
            ans = 2LL * d + 2;                       // 中间就能让车
        } else {
            int tu = isHub(u) ? 0 : minExcept(u, p1);
            int tv = isHub(v) ? 0 : minExcept(v, p2);
            int t = min(tu, tv);
            ans = (t >= INF) ? -1 : 2LL * d + 4 + 4LL * t;
        }
        buf += to_string(ans);
        buf += '\n';
    }
    cout << buf;
    return 0;
}
```

### 易错点

内部岔点不包括两个端点；端点岔点对应的是额外四步分支。最近岔点搜索要排除朝向另一水果的方向，否则会错误穿过无法错车的通道。

## A. 人品大爆发

### 题意

做 $n$ 道难度均为 $m$ 的题，每道增加 $\lceil0.8m\rceil$ 人品，求总增量。

<!-- reusable-foundations:start -->

### 从零讲：枚举与模拟：让代码和允许的动作一一对应

枚举是系统地检查所有候选；模拟是按题目规则推进状态。先写清一个候选是什么、有哪些动作、执行后哪些量改变，再决定循环边界。

例如从集合 $\{1,2,3\}$ 中选两个不同数：有序选择可枚举 $(i,j)$ 且 $i\ne j$，共六项；如果只关心无序的一对，就规定 $i<j$，得到 $(1,2)$、$(1,3)$、$(2,3)$，避免重复计数。同一个双循环，边界表达的是不同对象。

```cxx
for (int i = 0; i < n; ++i)
    for (int j = i + 1; j < n; ++j) {
        // 每一对不同位置恰好出现一次
    }
```

模拟例如计数器初始为零，依次读动作“加二、减一、加二”，状态为 $0\to2\to1\to3$。每一步都只读取该时刻允许的信息；若规则要求同时更新多个量，应先用旧状态算全部新量，不能让后一个更新误读前一个新值。

时间要数实际候选数和每个候选的工作。双循环可能是 $O(n^2)$，枚举长度为 $k$ 的二进制选择是 $O(2^k)$；候选少但每次又扫描全数组，也要乘上扫描成本。空间取决于是否需要保存历史。

全枚举的优势是思路直接，容易作为独立校验程序。剪枝必须证明被略去的分支不可能合法或更优，不能只因一个小例子没遇到答案就删候选。若直接枚举超时，先找重复工作、对称性、可维护的量或单调边界，再选择优化方法。

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cxx
int a = 100000, b = 100000;
long long wrong = a * b;      // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

<!-- reusable-foundations:end -->

### 思路

例如 $m=6$ 时，单题增加 $\lceil4.8\rceil=5$，做 $n$ 道就增加 $5n$。用整数上取整计算 $\lceil4m/5\rceil=(4m+4)/5$，答案乘 $n$。时间、空间 $O(1)$。

### 参考代码

```cpp
// A. 人品大爆发
// 一道难度为 m 的题，人品增长是 ceil(0.8 * m) = ceil(4m / 5)。
// 因为 n 道题难度全相同，单题收益是定值，总收益 = n * 单题收益。
// 整数上取整 (4m + 4) / 5 就是 floor 意义下的向上取整（m 是正整数）。
#include <bits/stdc++.h>
using namespace std;

int main() {
    long long n, m;
    cin >> n >> m;
    // 单题收益：ceil(4m / 5)，用整数运算避免浮点误差
    long long per = (4 * m + 4) / 5;
    // 总数最大 1e9 * 8 = 8e9，超出 int，必须用 long long
    cout << n * per << '\n';
    return 0;
}
```

### 易错点

先算单题上取整再乘题数；结果可能超过 32 位，使用 64 位整数。

## B. 魔法扑克牌

### 题意

一次操作给相邻两项同时加一或同时减一，判断数组 $a$ 能否变成 $b$。

<!-- reusable-foundations:start -->

### 从零讲：计数：先确定一个方案包含哪些选择

加法用于互斥类别，乘法用于逐步选择，除法用于消除确切的重复。公式每一项都应能对应一个实际对象，不能只凭“看起来有几个位置”相乘。

三个人中选两人且指定先后：第一人三种选择，第二人只能从剩下两人中选，得到六种。若只选一个无序小组，AB 和 BA 表示同组，每组恰数两次，除以二得到三组。

![六个有序选择按同一无序对配成三组，每组恰好出现两次](assets/foundations/counting.svg)

一般地，$n$ 个不同对象选 $k$ 个且排序有 $n(n-1)\cdots(n-k+1)$ 种；不区分内部顺序，恰有 $k!$ 个排列表示同一子集，所以

$$\binom nk=\frac{n!}{k!(n-k)!}.$$

这个除法成立依赖“每个最终对象被数同样多次”。若含相同元素、对称或禁用条件，重复倍数可能改变，要重新证明。比如组的内部无序和组之间无序是两种不同的对称性，不应混成一句“除去重复”。

互相独立不是乘法原则唯一的表述；逐步计数只需每种前序选择都有相同数量的后续选择。若后续数量随前序变化，就应分别计算后求和。

在模数下计算组合数时，普通整数除法不能直接替代分母逆元。若用阶乘和逆阶乘，须满足逆元存在等前提。答案可能指数增长，先确定取模或大整数方式；数值范围也决定预处理是否可行。

### 从零讲：vector：长度可变的连续数组

`vector<T>` 保存一串同类型的元素，适合按下标访问、扫描、排序。`T` 是元素类型，例如 `vector<int>` 保存整数，`vector<pair<int,int>>` 保存整数对，`vector<vector<int>>` 可保存每个顶点各自的邻居。需要 `<vector>`。

```cxx
vector<int> a(3, 7);   // 三个元素，内容是 7、7、7
a.push_back(9);       // 在末尾追加，现在长度为 4
int x = a[1];         // 从 0 编号，这里得到 7
a[1] = 2;            // 改第二个元素
int n = int(a.size());
```

`vector<int> a(3)` 创建三个值为零的元素；`a.reserve(3)` 只预留容量，元素数仍为零，此时不能访问 `a[0]`。长度 `size()` 与容量 `capacity()` 是不同概念。

下标访问为 $O(1)$，遍历为 $O(n)$。末尾追加通常为 $O(1)$；容量不足时会分配更大的连续空间并搬移元素，这次可能为 $O(n)$，一连串追加的平均成本称为摊还 $O(1)$。中间插入或删除会搬移后续元素，最坏 $O(n)$。内存是元素量的 $O(n)$，并可能预留部分尚未使用的容量。

`begin()` 指向首元素，`end()` 指向尾后位置，`sort(a.begin(),a.end())` 操作整个数组。`a[i]` 不检查越界；下标须满足 $0\le i<\mathrm{size}$。`at(i)` 会检查越界并抛异常。空数组不能访问 `front()`、`back()`；`pop_back()` 也要求非空。

扩容后指向旧存储的迭代器、引用和指针会失效。遍历的同时 `push_back`，不能假定此前取得的引用仍可用。读取大数组的函数常用 `const vector<int>& a` 按常量引用传入，既不复制也禁止通过该引用修改；`vector<int> a` 按值传参则复制内容。选择副本还是引用取决于是否要保留独立数据。

