### 从零讲：等比数列的结构与「候选公比只有两个」

等比数列的每项都是前一项乘固定公比。比如 $2,6,18,54$ 的公比为三；删掉六后，最小两项变成二、十八，它们的比值是公比的平方。

只缺一个数时，原数组最小两项 $s_1,s_2$ 在完整数列里要么相邻，要么中间恰少一项，所以 $s_2/s_1$ 只能是 $r$ 或 $r^2$。不需要尝试任意补入整数，而是从最前面两个数锁定至多两个公比，再验证整个序列。

### 思路

先按绝对值排序。若绝对值全相等，只可能取公比一或负一：同号时补同一个值；正负混合时分别检查两种交替模板能否只补一个符号。

其余情况把数列必要时反向，使绝对值公比 $r>1$，于是绝对值必须严格递增，有重复就无解。基础小节说明 $r$ 只有两个候选：$s_2/s_1$，或 $\sqrt{s_2/s_1}$。第二种成立时缺失项为 $\sqrt{s_1s_2}$，先检查它是否为整数。

对每个候选公比，用约分后的分数表示。最小项只能是 $s_1$，或者缺失的 $s_1/r$；分别尝试，从起点生成 $n+1$ 项，逐项检查整除与范围，再与原绝对值序列归并，要求恰好多一个元素。

最后检查四种符号模板：全正、全负、正负交替的两种起点。原数在模板中的符号全部匹配，即可输出。候选只有常数个，排序占主要时间 $O(n\log n)$，空间 $O(n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef __int128 lll;

static ll gcdll(ll a, ll b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b) { ll t = a % b; a = b; b = t; }
    return a;
}

// 整数平方根（v ≤ 1e18，ll 装得下）
static ll isqrtll(ll v) {
    if (v < 0) return -1;
    ll r = (ll)sqrtl((long double)v);
    while ((lll)r * r > v) r--;
    while ((lll)(r + 1) * (r + 1) <= v) r++;
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<ll> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];

        int m = n + 1;                       // 插入后一共 m 项
        // 按绝对值升序排好（等比数列的绝对值是单调的）
        vector<int> ord(n);
        for (int i = 0; i < n; i++) ord[i] = i;
        sort(ord.begin(), ord.end(), [&](int u, int v) {
            return (a[u] < 0 ? -a[u] : a[u]) < (a[v] < 0 ? -a[v] : a[v]);
        });
        vector<ll> s(n);
        for (int i = 0; i < n; i++) s[i] = (a[ord[i]] < 0 ? -a[ord[i]] : a[ord[i]]);

        bool same = true;
        for (int i = 1; i < n; i++) if (s[i] != s[0]) same = false;

        /* ---------- 情况一：所有 |a_i| 都相等 ---------- */
        if (same) {
            ll v = s[0];
            bool allpos = true, allneg = true;
            for (int i = 0; i < n; i++) {
                if (a[i] > 0) allneg = false; else allpos = false;
            }
            if (allpos || allneg) {
                // 公比 q = +1：所有项都是同一个数，插入同样的数即可
                cout << "Yes\n";
                for (int i = 0; i < m; i++) cout << a[0] << (i + 1 == m ? '\n' : ' ');
                continue;
            }
            // 正负混杂：|q| = 1 ⇒ q = −1，序列正负交替；数一数正负各几个
            ll pos = 0, neg = 0;
            for (int i = 0; i < n; i++) (a[i] > 0 ? pos : neg)++;
            bool done = false;
            for (int startPlus = 1; startPlus >= 0 && !done; startPlus--) {
                // 从 +v 开头的模板里正号 ceil(m/2) 个、负号 floor(m/2) 个；从 −v 开头则相反
                ll cp = startPlus ? (m + 1) / 2 : m / 2;
                ll cn = m - cp;
                ll xs = 0;
                if (pos + 1 == cp && neg == cn) xs = 1;        // 缺的那个是 +v
                else if (pos == cp && neg + 1 == cn) xs = -1;  // 缺的那个是 −v
                if (xs == 0) continue;
                cout << "Yes\n";
                for (int i = 1; i <= m; i++) {
                    bool plus = startPlus ? (i % 2 == 1) : (i % 2 == 0);
                    cout << (plus ? v : -v) << (i == m ? '\n' : ' ');
                }
                done = true;
            }
            if (!done) cout << "No\n";
            continue;
        }

        /* ---------- 情况二：|a_i| 不全相等 ---------- */
        // 此时若合法必然 |q| > 1，而 |q| > 1 的等比数列各项绝对值两两不同
        bool dup = false;
        for (int i = 1; i < n; i++) if (s[i] == s[i - 1]) dup = true;
        if (dup) { cout << "No\n"; continue; }

        // 可能的公比只有两个：|s_2/s_1|，或它的平方根（插入的数夹在 s_1 与 s_2 中间时）
        vector<pair<ll, ll>> cand;                 // 公比 = p / q > 1
        {
            ll g = gcdll(s[1], s[0]);
            cand.push_back({s[1] / g, s[0] / g});
        }
        {
            ll t = isqrtll(s[0] * s[1]);
            if (t > 0 && (lll)t * t == (lll)s[0] * (lll)s[1]) {
                ll g = gcdll(t, s[0]);
                ll p = t / g, q = s[0] / g;
                if (p != cand[0].first || q != cand[0].second) cand.push_back({p, q});
            }
        }

        bool done = false;
        for (size_t ci = 0; ci < cand.size() && !done; ci++) {
            ll p = cand[ci].first, q = cand[ci].second;

            // 两个起点：绝对值最小的那项就是插入的 x（起点 = s_1 / r），否则起点 = s_1
            vector<ll> starts;
            starts.push_back(s[0]);
            {
                lll num = (lll)s[0] * q;
                if (num % (lll)p == 0) {
                    ll v1 = (ll)(num / (lll)p);
                    if (v1 >= 1) starts.push_back(v1);
                }
            }

            for (size_t si = 0; si < starts.size() && !done; si++) {
                // 顺着公比生成全部 m 项
                vector<ll> V;
                V.push_back(starts[si]);
                bool ok = true;
                for (int i = 1; i < m; i++) {
                    lll nx = (lll)V.back() * (lll)p;
                    if (nx % (lll)q != 0) { ok = false; break; }
                    lll cur = nx / (lll)q;
                    if (cur > (lll)1000000000000000000LL) { ok = false; break; }
                    V.push_back((ll)cur);
                }
                if (!ok) continue;

                // 和 s 归并比对：恰好有一个 V 里的元素不在 s 里（那就是插入的 x）
                int i = 0, j = 0, extra = -1;
                bool bad = false;
                while (i < m && j < n) {
                    if (V[i] == s[j]) { i++; j++; }
                    else if (V[i] < s[j]) {
                        if (extra != -1) { bad = true; break; }
                        extra = i; i++;
                    } else { bad = true; break; }
                }
                while (!bad && i < m) {
                    if (extra != -1) { bad = true; break; }
                    extra = i; i++;
                }
                if (bad || j != n || extra == -1) continue;

                // 四种符号模板：全 +、全 −、正负交替（两种相位）
                for (int tpl = 0; tpl < 4 && !done; tpl++) {
                    bool good = true;
                    for (int t = 0; t < n && good; t++) {
                        int vi = (t < extra) ? t : t + 1;      // 这个元素在 V 里的下标（跳过 extra）
                        bool plus;
                        if (tpl == 0) plus = true;
                        else if (tpl == 1) plus = false;
                        else if (tpl == 2) plus = (vi % 2 == 0);
                        else plus = (vi % 2 == 1);
                        if ((a[ord[t]] > 0) != plus) good = false;
                    }
                    if (!good) continue;
                    cout << "Yes\n";
                    for (int t = 0; t < m; t++) {
                        bool plus;
                        if (tpl == 0) plus = true;
                        else if (tpl == 1) plus = false;
                        else if (tpl == 2) plus = (t % 2 == 0);
                        else plus = (t % 2 == 1);
                        cout << (plus ? V[t] : -V[t]) << (t + 1 == m ? '\n' : ' ');
                    }
                    done = true;
                }
            }
        }
        if (!done) cout << "No\n";
    }
    return 0;
}
```

### 易错点

不能用浮点误差判断公比、整除或完全平方。符号交替模板应在插入后的下标上检查；补在中间会改变后面所有项的奇偶位置。

## A. 出题需要 rating

### 题意

初始评分为一千，按顺序加上每次评分变化，统计每次变化后所在段位的次数，不计初始状态。

<!-- reusable-foundations:start -->

### 从零讲：枚举与模拟：让代码和允许的动作一一对应

枚举是系统地检查所有候选；模拟是按题目规则推进状态。先写清一个候选是什么、有哪些动作、执行后哪些量改变，再决定循环边界。

例如从集合 $\{1,2,3\}$ 中选两个不同数：有序选择可枚举 $(i,j)$ 且 $i\ne j$，共六项；如果只关心无序的一对，就规定 $i<j$，得到 $(1,2)$、$(1,3)$、$(2,3)$，避免重复计数。同一个双循环，边界表达的是不同对象。

```cxx
for (int i = 0; i < n; ++i)
    for (int j = i + 1; j < n; ++j) {
        // 每一对不同位置恰好出现一次
    }
```

模拟例如计数器初始为零，依次读动作“加二、减一、加二”，状态为 $0\to2\to1\to3$。每一步都只读取该时刻允许的信息；若规则要求同时更新多个量，应先用旧状态算全部新量，不能让后一个更新误读前一个新值。

时间要数实际候选数和每个候选的工作。双循环可能是 $O(n^2)$，枚举长度为 $k$ 的二进制选择是 $O(2^k)$；候选少但每次又扫描全数组，也要乘上扫描成本。空间取决于是否需要保存历史。

全枚举的优势是思路直接，容易作为独立校验程序。剪枝必须证明被略去的分支不可能合法或更优，不能只因一个小例子没遇到答案就删候选。若直接枚举超时，先找重复工作、对称性、可维护的量或单调边界，再选择优化方法。

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cxx
int a = 100000, b = 100000;
long long wrong = a * b;      // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

### 从零讲：用真假值选择字符串里的一个字符

字符串字面量 `" \n"` 依次存放空格、换行和结尾的空字符。下标从零开始，所以 `[0]` 取空格，`[1]` 取换行。比较式产生bool值，作为数组下标时，false转换成0，true转换成1。

```cxx
int data[] = {4, 9, 2};
for (int i = 0; i < 3; ++i) {
    cout << data[i] << " \n"[i == 2];
}
// 输出4、空格、9、空格、2、换行
```

`i == 2` 在前两次为假，选第零个字符；最后一次为真，选第一个字符。因此输出的是一个分隔字符，而非整个字符串。它等价于在每次输出数值后，用if判断是否已到最后一项，再分别输出换行或空格。条件必须和实际最后下标相符。

字面量长度加上结尾空字符才是数组大小；这里只访问下标0或1，不触及结尾空字符。不能拿任意较大整数作下标，越界访问不合法。普通字符下标访问是 $O(1)$，输出n项仍需 $O(n)$ 次处理。写法较紧凑，但条件复杂时使用清晰的if/else更容易阅读。

<!-- reusable-foundations:end -->

### 思路

维护当前评分，先加本次变化，再用题目给定的分界 700、1100、1500、2000、2400、2800 判断段位并计数。每次只需比较常数个阈值，时间 $O(n)$，额外空间 $O(1)$。

### 一场比赛只给一个赛后记录加一次

![同一评分数轴上的七个互斥段位，1000加100到1100记蓝名，再减401到699记灰名](assets/editorial-reasoning/core27-rating-records.svg)

图中两场变化为+100和−401：先从1000更新到1100，再给蓝名加一；下一场从1100更新到699，再给灰名加一。初始1000没有对应赛后记录，七个计数器从零开始。

评分非负由原题保证，所以第一档的下界0已经成立。对后续各档，从低段位向高段位试上界时，走到第c档说明此前的上界都没有严格大于当前分数，因此已经保证了该档的下界；再有 `rating < up[c]` 就同时满足这一档的上下界。边界1100跳过紫名，属于蓝名。各档互斥，找到后break避免为同一场再计一次；全部非负分数又被七档覆盖，所以每场恰贡献一次，最后计数之和为n。由原约束，评分最高 $1000+1000n\le100001000$，远小于最后的 `LLONG_MAX`，红名记录也一定能命中。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    long long rating = 1000;      // 小鲨鱼的初始 rating
    long long cnt[7] = {0};       // 依次是 灰 / 紫 / 蓝 / 青 / 黄 / 橙 / 红
    // 每一档的「上界（不含）」：灰 <700、紫 <1100、蓝 <1500、青 <2000、
    // 黄 <2400、橙 <2800、红没有上界。
    const long long up[7] = {700, 1100, 1500, 2000, 2400, 2800, LLONG_MAX};

    for (int i = 0; i < n; i++) {
        long long a;
        cin >> a;
        rating += a;              // 本场比赛结束后的 rating
        // 找出它落在哪一档：第一个满足 rating < up[c] 的档就是答案
        for (int c = 0; c < 7; c++) {
            if (rating < up[c]) {
                cnt[c]++;
                break;
            }
        }
    }

    for (int c = 0; c < 7; c++) cout << cnt[c] << " \n"[c == 6];
    return 0;
}
```

### 易错点

边界分数属于较高的一档；初始的一千分没有对应一场比赛，不应计数。

## B. 出题需要语文

### 题意

从 A 至 F 六类题中各选一道，要求每道分数至少六十、总分至少四百二十，输出可行的题目编号。

<!-- reusable-foundations:start -->

### 从零讲：贪心：先证明当前选择不会丢掉最优解

贪心每一步确定一个局部选择，不再撤回。它能省去搜索，但必须解释为什么始终存在一个最优方案也做这个选择。

例如选择最多个互不重叠的活动（这里允许后一活动起点等于前一活动终点）。每次选结束最早的活动：若最优方案的首项结束更晚，把它换成最早结束者，后续原本能接的活动仍能接，数量不变。这就是交换论证；换完首项，剩余问题仍为同类问题。

![结束更早的首项留下不少于另一选择的可用时间](assets/foundations/greedy.svg)

实现时按结束时间升序排序，维护上一次选中活动的结束时刻，依次选合法项。排序 $O(n\log n)$，扫描 $O(n)$，保存活动为 $O(n)$。若题目不允许端点相接，判断须从大于等于改成严格大于。

“选最长”“选价值最高”“选最靠左”都是不同策略。没有交换、支配关系或不变量的依据，不能只凭排序键直觉宣布正确。比如有容量和价值的物品选择，眼前价值最高者可能挡住两个总价值更高的小物品。

写题解时说明被替换的是哪一项、替换后什么约束仍满足、目标为何不变差，并说明余下状态为何允许重复同样论证。若选择还影响未保存的条件，就可能需要更丰富的状态或动态规划。

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cxx
int a = 100000, b = 100000;
long long wrong = a * b;      // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

<!-- reusable-foundations:end -->

### 思路

每类选最高分题即可。若某类最高分仍不足六十，该类没有合法选择；若六个最高分之和不足四百二十，其他组合只会更低。反过来，六个最大值满足要求时，其编号就是一组解。扫描维护每类最大分及编号，时间 $O(n)$，空间 $O(1)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    // bestQ[d] / bestId[d]：难度为 d（0=A、1=B … 5=F）的题里，
    // 质量不低于 60 的那批中质量最大的题（质量、下标）。
    int bestQ[6], bestId[6];
    for (int d = 0; d < 6; d++) {
        bestQ[d] = -1;
        bestId[d] = -1;
    }

    for (int i = 1; i <= n; i++) {
        char d;
        int q;
        cin >> d >> q;
        int id = d - 'A';
        if (q < 60) continue;                       // 质量低于 60 的题一律不能选
        if (q > bestQ[id]) {                        // 同难度里只留质量最大的那道
            bestQ[id] = q;
            bestId[id] = i;
        }
    }

    long long sum = 0;
    bool ok = true;
    for (int d = 0; d < 6; d++) {
        if (bestId[d] < 0) ok = false;              // 这个难度根本没有能选的题
        else sum += bestQ[d];
    }

    // 6 道题平均质量不低于 70 ⟺ 质量之和不少于 420
    if (!ok || sum < 420) {
        cout << -1 << "\n";
        return 0;
    }

    for (int d = 0; d < 6; d++) cout << bestId[d] << " \n"[d == 5];
    return 0;
}
```

### 易错点

每类必须选恰好一道；有并列最高分时保留任意一个编号即可。

## C. 出题需要加法

### 题意

多次查询区间内有多少个数能写成两个非负整数次幂的二的和，两个指数可以相同。

<!-- reusable-foundations:start -->

### 从零讲：位运算：把非负整数看成一组二进制开关

五写成二进制为 $0101_2$，三为 $0011_2$。同一列各代表一位：按位与 `&` 两边都为一才得一，按位或 `|` 任一为一就得一，按位异或 `^` 不同才为一。所以 $5\mathbin{\&}3=1$，$5\mathbin{|}3=7$，$5\mathbin{\oplus}3=6$。

![相同数值分别写成每一位，逐列计算与、或、异或](assets/foundations/bits.svg)

`1ULL << k` 把一移到第 $k$ 位。对非负无符号整数，`(mask >> k) & 1ULL` 读该位，`mask | (1ULL<<k)` 置一，`mask & ~(1ULL<<k)` 清零，`mask ^ (1ULL<<k)` 翻转。最低位编号为零。

```cxx
unsigned long long mask = 5; // 第 0、2 位为一
bool has = (mask >> 2) & 1ULL; // true
mask |= 1ULL << 1;             // 变成 7
```

位移次数必须小于类型位宽，且不能为负；不要用普通 `1` 去移到超出 int 范围的位置。C++17 有符号负数右移和溢出的规则不适合直接套“乘除二的幂”，用明确范围的无符号数更容易保证行为。`^` 是异或，绝不是乘方。

逻辑与 `&&`、逻辑或 `||` 将整体条件视为真假，并会短路；按位 `&`、`|` 逐位计算，不会因此跳过右侧表达式。运算符优先级可能与直觉不同，写 `(mask & bit) != 0`，别省掉关键括号。

固定机器字内的一次位运算按 $O(1)$ 估算；枚举全部 $k$ 位状态仍有 $2^k$ 种，不能因为每次运算快就忽略状态数。`x & (x-1)` 对正无符号数清掉最低的一位；GCC 的 `__builtin_popcountll(x)` 统计一的数量，注意实参位宽与具体编译器支持。

### 从零讲：计数：先确定一个方案包含哪些选择

加法用于互斥类别，乘法用于逐步选择，除法用于消除确切的重复。公式每一项都应能对应一个实际对象，不能只凭“看起来有几个位置”相乘。

三个人中选两人且指定先后：第一人三种选择，第二人只能从剩下两人中选，得到六种。若只选一个无序小组，AB 和 BA 表示同组，每组恰数两次，除以二得到三组。

![六个有序选择按同一无序对配成三组，每组恰好出现两次](assets/foundations/counting.svg)

一般地，$n$ 个不同对象选 $k$ 个且排序有 $n(n-1)\cdots(n-k+1)$ 种；不区分内部顺序，恰有 $k!$ 个排列表示同一子集，所以

$$\binom nk=\frac{n!}{k!(n-k)!}.$$

这个除法成立依赖“每个最终对象被数同样多次”。若含相同元素、对称或禁用条件，重复倍数可能改变，要重新证明。比如组的内部无序和组之间无序是两种不同的对称性，不应混成一句“除去重复”。

互相独立不是乘法原则唯一的表述；逐步计数只需每种前序选择都有相同数量的后续选择。若后续数量随前序变化，就应分别计算后求和。

在模数下计算组合数时，普通整数除法不能直接替代分母逆元。若用阶乘和逆阶乘，须满足逆元存在等前提。答案可能指数增长，先确定取模或大整数方式；数值范围也决定预处理是否可行。

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cxx
int a = 100000, b = 100000;
long long wrong = a * b;      // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

<!-- reusable-foundations:end -->

### 思路

若指数不同，二进制恰有两个一；若指数相同，两个幂进位成一个一，但最小结果是二。因此只需计数二进制一的个数为一或二的数，再排除数字一。

记 $g_c(N)$ 为不超过 $N$ 且恰有 $c$ 个一的数的数量。从高位向低位扫描 $N$：遇到一个一，可以让构造数此位取零，立刻变小，此后的 $i$ 个低位任取所需的一，共 $\binom{i}{c-u}$ 种；这里 $u$ 是此前已跟随的一数。然后本位继续取一，令 $u$ 加一。最后若 $N$ 自身一数为 $c$，再加一。

前缀答案为 $g_1(N)+g_2(N)-[N\ge1]$，区间答案作前缀差。组合数预处理后每次查询 $O(\log N)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

typedef unsigned long long ull;

// 数 [0, N] 里二进制恰好有 c 个 1 的整数个数（只用 c = 1 / 2）。
//
// 从高位往低位扫：遇到 N 的某一位是 1，就让这一位取 0、更高位与 N 完全相同，
// 于是低 i 位可以随意填 —— 还需 need = c - used 个 1，方案数就是 C(i, need)。
long long countBits(ull N, int c) {
    long long res = 0;
    int used = 0;                     // 已经固定的 1 的个数
    for (int i = 62; i >= 0; i--) {
        if ((N >> i) & 1ULL) {
            int need = c - used;      // 在低 i 位里还要挑几个 1
            if (need == 0) res += 1;
            else if (need == 1) res += i;
            else if (need == 2) res += (long long)i * (i - 1) / 2;
            used++;
            if (used > c) break;      // 已固定的 1 超过 c 个，后面不可能再补回来
        }
    }
    if (used == c) res += 1;          // N 自己也算一个
    return res;
}

// [1, N] 里「可合数」的个数：w = 2^x + 2^y ⟺ w 的二进制里恰好 1 或 2 个 1，
// 唯一的例外是 w = 1（它只有 1 个 1，却凑不出 2^x+2^y，因为最小是 2）。
long long countUpTo(ull N) {
    long long r = countBits(N, 1) + countBits(N, 2);
    if (N >= 1) r -= 1;               // 把 1 减掉
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        ull L, R;
        cin >> L >> R;
        ull left = (L == 0) ? 0 : L - 1;   // [L,R] 的答案 = 前缀 [1,R] 减前缀 [1,L-1]
        cout << countUpTo(R) - countUpTo(left) << "\n";
    }
    return 0;
}
```

### 易错点

允许两个指数相等，所以不能只统计两个一；零不是答案，数字一也不是两个非负指数幂的和。左端为零时单独处理前缀。

## D. 出题需要构造

### 题意

给 $n\times m$ 网格染上编号 $1$ 至 $n$ 的颜色，要求无论选哪 $k$ 种颜色点亮，每行、每列都恰有两个亮格；构造网格和 $k$，或判断无解。

<!-- reusable-foundations:start -->

### 从零讲：构造：找到一份合法对象，并解释它为何总能生成

构造题允许输出任意满足要求的对象。先区分“只需合法”与“还要求最小、最多或字典序最小”，不要额外发明优化目标。

例如要把从一到 $2k$ 的数字配成 $k$ 对，使每对和相同，可以配 $(1,2k),(2,2k-1),\ldots,(k,k+1)$，每对都为 $2k+1$。数字不重复，因为两半各用一次；也没有漏数。这个一般描述能直接转成循环。

![两端相向配对，每个数恰被使用一次且每对和相同](assets/foundations/construction.svg)

如果还要求最大化某项，先给任何方案都不能超越的上界，再展示构造确实达到上界；没有最优性要求时只证明合法和能完成即可。

一个完整构造应能回答：什么时候无解；输出对象是什么；每次允许的动作如何执行；后续所需的条件有没有被前面的动作破坏；数量、范围和边界是否满足。操作题还要区分目标排列和真正输出的操作序列。

验证构造不能只和另一程序逐字比较，因为合法答案可有多份。应将结果代回题目条件：检查长度、元素多重集合、限制、每步前后状态及目标。复杂度按生成和校验成本计算，输出本身有 $k$ 项就至少需要 $O(k)$ 时间。

<!-- reusable-foundations:end -->

### 思路

一次点亮后，按行计数亮格共 $2n$ 个，按列计数共 $2m$ 个，所以必须 $n=m$；每行至少要有两格，又要求 $n\ge2$。

这两个条件也充分：取 $k=2$，按循环拉丁方染色，零基坐标 $(i,j)$ 的颜色为 $(i+j)\bmod n+1$。每行每列各出现一次所有颜色，无论选哪两种都恰好点亮两格。

![循环拉丁方的每行每列都包含全部颜色](assets/d-latin.svg)

输出耗时 $O(n^2)$，额外空间 $O(1)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n, m;
        cin >> n >> m;

        // 条件「对任意 k 种颜色都恰好每行每列 2 个」逼出：k = 2 且 n = m >= 2。
        if (n != m || n < 2) {
            cout << "NO\n";
            continue;
        }

        // 取 k = 2，用最朴素的拉丁方：第 i 行第 j 列填 (i+j) mod n + 1。
        // 每行、每列都是 1..n 的一个排列，所以任取两种颜色，
        // 每行恰好 2 个、每列也恰好 2 个。
        cout << "YES\n2\n";
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                cout << (i + j) % n + 1 << " \n"[j == n - 1];
            }
        }
    }
    return 0;
}
```

### 易错点

必要条件来自同一批亮格的两种计数，不必枚举颜色集合。$n=m=1$ 仍无解。

