### 从零讲：子树里 1 的个数，决定了哪些状态走得到

一只能向祖先移动，因此每棵子树最终保留的一数 $B_u$ 不超过初值 $A_u$，差额 $D_u$ 就是必须跨父边送出的数量。总数不变意味着根没有向外送出的量。

非负差额也保证能完成搬动：从最深正差额处向上找可接收的一处零，将相邻的一上移；若一路都为一，差额会传到根，与根差额零矛盾。每一步只减少一条边的待送数量，直到全部为零。因此这些差额既描述可达性，也直接计量最少操作数。

### 思路

对终态定义差额 $D_u=A_u-B_u$。可达条件是所有差额非负、根差额为零，并满足逐点上界。

每次有效上移只让经过那条父边所对应子树的一数减少一，故只让一个 $D_u$ 减一。从初态到目标恰需 $\sum_uD_u$ 次；必要性来自每条边的净流出量，充分性来自基础小节的上移构造，根项为零。

树上背包按向父亲送出的数量 $d$ 维护二元状态 $(W,C)$，分别为终态方案数、这些方案的操作数总和。合并两个孩子状态时，方案数相乘，代价变为 $C_1W_2+W_1C_2$，因为一侧每个方案都要搭配另一侧全部方案。

孩子合计送来 $S$ 后，当前点选择保留 $b_u\in\{0,1\}$ 且 $b_u\le s_u$，向上送出 $d=a_u+S-b_u\ge0$。方案数不变，代价增加 $dW$，计入当前父边的移动次数。根只取 $d=0$ 的代价总和。

时间 $O(n^2)$，及时释放孩子数组后空间 $O(n)$。

### 参考代码

```cpp
// 牛客练习赛 152 E. 交换（Hard Version）
//
// 关键结论（详见题解「从零讲」）：
//   1) 一次交换只有在「父亲是 0、儿子是 1」时才真正改变状态，效果是把那个 1 向上搬一层；
//      所以每个 1 只能往上走，永远不能往下走，也越不过另一个 1。
//   2) 于是状态 b 可达 ⟺ 全树 1 的总数不变，且对每个节点 v：B(v) ≤ A(v)，
//      其中 A(v)/B(v) 分别是初始/最终状态里 v 的子树中 1 的个数。
//   3) 记 D(v) = A(v) - B(v)，它是「从 v 往父亲送上去的 1 的个数」。每次有效交换只让
//      恰好一个子树的 1 个数减 1，所以最少操作次数 = Σ_v D(v)。
//   4) 换个说法：节点 v 收下孩子送来的 Σ_c D(c) 个 1，加上自己原有的 a_v 个，留下 b_v 个
//      （0 或 1，s_v = 0 时只能留 0），剩下的 D(v) 个继续往上送。
//      合法状态 ⟺ 所有 D(v) ≥ 0 且 D(根) = 0；每个状态的代价恰好是 Σ_v D(v)。
//      这两件事都能在树上背包里边算边累加，于是 O(n^2) 解决。

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<vector<int>> g(n + 1);                 // 邻接表（题目给的是无向边）
        for (int i = 0; i < n - 1; i++) {
            int u, v;
            cin >> u >> v;
            g[u].push_back(v);
            g[v].push_back(u);
        }
        vector<int> a(n + 1), s(n + 1);
        for (int i = 1; i <= n; i++) cin >> a[i];     // 初始权值 a_i
        for (int i = 1; i <= n; i++) cin >> s[i];     // 最终权值上界 s_i

        // ---- 以 1 为根，求出每个点的父亲与「父亲先于儿子」的顺序 ----
        vector<int> par(n + 1, 0), order;
        order.reserve(n);
        vector<int> stk;
        stk.push_back(1);
        par[1] = 0;                                   // 根的「父亲」记 0，表示没有
        while (!stk.empty()) {
            int v = stk.back();
            stk.pop_back();
            order.push_back(v);
            for (int to : g[v]) {
                if (to == par[v]) continue;           // 不走回父亲
                par[to] = v;
                stk.push_back(to);
            }
        }
        // A[v] = 初始状态里子树 v 中 1 的个数（逆序处理 = 孩子先于父亲）
        vector<int> A(n + 1, 0);
        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];
            A[v] += a[v];
            if (par[v]) A[par[v]] += A[v];
        }

        // ---- 树上背包：dp_v[d] = (方案数, 方案代价和)，d = D(v) ----
        // 代价 = 该子树内的 Σ D(w)，单位就是操作次数
        vector<vector<ll>> W(n + 1), C(n + 1);
        for (int i = n - 1; i >= 0; i--) {            // 逆序：孩子全部算完才算父亲
            int v = order[i];
            // 先把所有孩子按 S = Σ_c D(c) 卷积起来
            vector<ll> accW(1, 1), accC(1, 0);        // 还没有孩子时：S = 0，方案数 1，代价 0
            for (int to : g[v]) {
                if (to == par[v]) continue;           // 父亲不是孩子
                int lb = (int)W[to].size();           // 孩子的 D 取值范围是 [0, A[to]]
                int lc = min((int)accW.size() - 1 + lb - 1, A[v]) + 1;  // S ≤ Σ_c A(c) ≤ A[v]
                vector<ll> nW(lc, 0), nC(lc, 0);
                for (int x = 0; x < (int)accW.size(); x++) {
                    for (int y = 0; y < lb && x + y < lc; y++) {
                        // 两部分的方案数相乘、代价各自乘对方的方案数再相加
                        ll w = accW[x] * W[to][y] % MOD;
                        nW[x + y] = (nW[x + y] + w) % MOD;
                        nC[x + y] = (nC[x + y] + accC[x] * W[to][y] + accW[x] * C[to][y]) % MOD;
                    }
                }
                accW.swap(nW);
                accC.swap(nC);
                vector<ll>().swap(W[to]);             // 孩子算完就释放，省内存
                vector<ll>().swap(C[to]);
            }
            // 在 v 处决策：留下 b_v 个（b_v ≤ s_v），必须有 D(v) = a_v + S - b_v ≥ 0
            W[v].assign(A[v] + 1, 0);
            C[v].assign(A[v] + 1, 0);
            for (int S = 0; S < (int)accW.size(); S++) {
                if (!accW[S] && !accC[S]) continue;
                for (int b = 0; b <= s[v]; b++) {     // s_v = 0 时只有 b = 0 这一种选择
                    int d = a[v] + S - b;             // d = D(v) = 往父亲送上去的个数
                    if (d < 0 || d > A[v]) continue;  // d < 0 说明手上不够留，非法
                    W[v][d] = (W[v][d] + accW[S]) % MOD;
                    // 代价多出 D(v) 个「跨越边 (父亲, v) 的 1」，每个方案各加一次
                    C[v][d] = (C[v][d] + accC[S] + (ll)d * accW[S]) % MOD;
                }
            }
        }
        // D(根) = 0 表示 1 的总数守恒；它的代价和就是所有合法状态的最小操作次数之和
        cout << C[1][0] % MOD << "\n";
    }
    return 0;
}
```

### 易错点

题目求各终态最短次数的总和，不是操作序列数量。合并费用必须交叉乘另一侧方案数，不能只把两个费用总和相加。

## F. 排列

### 题意

统计长 $n$ 排列中，前 $t$ 项内部正序对数落在 $[l,r]$ 的排列数。查询保证 $r\le2t$，不同 $t$ 的总和受限。

