### 思路

所有不同警察局一起做多源 BFS，每个新城市只保留首次发现它的那条边。这样得到每个分量一个警察局的森林，路径长度就是最近警局距离≤d。若有 s 个不同警局，至多分成 s 块，所以最多删 s-1 条边；保留森林达到此上界。

![多源扩展保留各自父边](assets/graph-lab/796D.svg)

删除两片 BFS 领地之间的边，每座城市仍通往自己的警局。

### 复杂度

时间 O(n+k)，空间 O(n)。原题保证覆盖距离，森林保留的最近路线不会变长。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll INF = (1LL << 62);
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k, d;
    cin >> n >> k >> d;
    vector<bool> seen(n + 1), keep(n);
    queue<int> q;
    for (int i = 0, u; i < k; i++) {
        cin >> u;
        if (!seen[u]) {
            seen[u] = true;
            q.push(u);
        }
    }
    vector<vector<pair<int, int>>> g(n + 1);
    for (int i = 1, u, v; i < n; i++) {
        cin >> u >> v;
        g[u].push_back({v, i});
        g[v].push_back({u, i});
    }
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (auto [v, id] : g[u])
            if (!seen[v]) {
                seen[v] = true;
                keep[id] = true;
                q.push(v);
            }
    }
    vector<int> ans;
    for (int i = 1; i < n; i++)
        if (!keep[i])
            ans.push_back(i);
    cout << ans.size() << '\n';
    for (int id : ans)
        cout << id << ' ';
}
```

