### 思路

从任意空格 DFS，按首次发现顺序保留前 s-k 个，其余改成 X。每个新发现点的父亲已经在前缀中，因此任意发现前缀都是连通的。不能随便按坐标选 k 个删掉。

![发现顺序的前缀保持连通](assets/graph-lab/377A.svg)

保留 1、2、3；新加入的每格都连着一个已保留父格。

### 复杂度

时间 O(nm)，空间 O(nm)，显式栈适合长走廊。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll INF = (1LL << 62);
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k;
    cin >> n >> m >> k;
    vector<string> a(n);
    vector<pair<int, int>> order, st;
    vector<vector<bool>> seen(n, vector<bool>(m));
    int s = 0;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        for (int j = 0; j < m; j++)
            if (a[i][j] == '.') {
                s++;
                if (st.empty())
                    st.push_back({i, j});
            }
    }
    seen[st[0].first][st[0].second] = true;
    int dx[] = {1, -1, 0, 0}, dy[] = {0, 0, 1, -1};
    while (!st.empty()) {
        auto [x, y] = st.back();
        st.pop_back();
        order.push_back({x, y});
        for (int d = 0; d < 4; d++) {
            int u = x + dx[d], v = y + dy[d];
            if (u >= 0 && u < n && v >= 0 && v < m && a[u][v] == '.' && !seen[u][v]) {
                seen[u][v] = true;
                st.push_back({u, v});
            }
        }
    }
    for (int i = s - k; i < s; i++)
        a[order[i].first][order[i].second] = 'X';
    for (auto &row : a)
        cout << row << '\n';
}
```

