### 思路

设整树异或为 S。S=0 时任意切一条边两边异或相等。S≠0 时需要 k≥3，并能切出两个不重叠、异或均为 S 的块；剩下部分也为 S。后序 DFS 找到异或 S 的非根子树后把贡献清零，防止它被祖先再次计入同一块。

![S 非零时寻找三块](assets/graph-lab/1592C.svg)

三块异或均为 S，合起来 S XOR S XOR S = S。

### 复杂度

时间 O(n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll INF = (1LL << 62);
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n, k;
        cin >> n >> k;
        vector<int> a(n), p(n, -1), order{0};
        int all = 0;
        for (int &x : a) {
            cin >> x;
            all ^= x;
        }
        vector<vector<int>> g(n);
        for (int i = 1, u, v; i < n; i++) {
            cin >> u >> v;
            --u;
            --v;
            g[u].push_back(v);
            g[v].push_back(u);
        }
        for (int i = 0; i < n; i++) {
            int u = order[i];
            for (int v : g[u])
                if (v != p[u]) {
                    p[v] = u;
                    order.push_back(v);
                }
        }
        int pieces = 0;
        for (int i = n - 1; i > 0; i--) {
            int u = order[i];
            if (a[u] == all) {
                pieces++;
                a[u] = 0;
            }
            a[p[u]] ^= a[u];
        }
        cout << ((all == 0 || (k >= 3 && pieces >= 2)) ? "YES" : "NO") << '\n';
    }
}
```

