#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    for (int &x : a)
        cin >> x;
    sort(a.begin(), a.end());
    int x = k == 0 ? 1 : a[k - 1];
    if ((k == 0 && a[0] == 1) || (k < n && a[k] <= x))
        cout << -1 << '\n';
    else
        cout << x << '\n';
}
