### 思路：连通块内所有点度数为二

遍历每个未访问顶点所在的完整连通分量，检查其中每个顶点的度数是否都为 2。全部为 2 才计入答案；发现不合格顶点也要把整块遍历完，避免重复计数。

### 边界与手算

用显式栈记录待访问点，入栈时标记，防止重边式重复入栈。深链可能有二十万个点，不用递归 DFS，避免栈溢出。

### 复杂度

时间 O(n+m)，邻接表和访问数组 O(n+m)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n);
    while (m--) {
        int u, v;
        cin >> u >> v;
        --u;
        --v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    vector<int> seen(n);
    int answer = 0;
    for (int s = 0; s < n; s++)
        if (!seen[s]) {
            bool cycle = true;
            vector<int> st{s};
            seen[s] = 1;
            while (!st.empty()) {
                int u = st.back();
                st.pop_back();
                if (g[u].size() != 2)
                    cycle = false;
                for (int v : g[u])
                    if (!seen[v]) {
                        seen[v] = 1;
                        st.push_back(v);
                    }
            }
            answer += cycle;
        }
    cout << answer << '\n';
}
```

